window.AUTH=window.AUTH||{};window.AUTH["17-1498"]={"d":"17-1498","id":"2019/17-1498","n":"Atlantic Richfield Co. v. Christian, et al.","briefs":[{"k":"petitioner","label":"Brief of petitioner Atlantic Richfield Co.","date":"2019-08-21","url":"https://www.supremecourt.gov/DocketPDF/17/17-1498/113101/20190821145345025_Atlantic%20Richfield%20Petitioner%20Brief%20No.%2017-1498.pdf","side":"pet","n":42},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2019-08-28","url":"https://www.supremecourt.gov/DocketPDF/17/17-1498/113991/20190828160614271_17-1498%20Atlantic%20Richfield%20Company.pdf","side":"us","n":72},{"k":"respondent","label":"Brief of respondents Gregory A. Christian, et al.","date":"2019-10-15","url":"https://www.supremecourt.gov/DocketPDF/17/17-1498/119002/20191015150038386_Christian%20Response%20Brief%20and%20Statutory%20Appendix.pdf","side":"res","n":111},{"k":"reply","label":"Reply of petitioner Atlantic Richfield Co.","date":"2019-11-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-1498/122434/20191114140647109_Atlantic%20Richfield%20Reply%20Brief.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/590US1PP_web.pdf#page=17","tr":true,"items":[{"t":"case","label":"Ali v. Federal Bureau of Prisons","cite":"552 U.S. 214","y":2008,"id":"2007/06-9130","sc":1,"sum":"The Court agreed with the 11th Circuit and, in a 5-4 majority opinion written by Justice Clarence Thomas, held that the use of the word \"any\" should be given its normal interpretation, encompassing all federal officers whether or not they were involved in enforcing customs or excise laws.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"American Electric Power Co. v. Connecticut","cite":"564 U.S. 410","y":2011,"id":"2010/10-174","sc":1,"sum":"The Court held that held the Clean Air Act bars suits by governmental bodies and private parties seeking to curb emissions from utilities via the federal common law.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"ARCO Environmental Remediation, L.L.C. v. Department of Health & Environmental Quality of Montana","cite":"213 F.3d 1108","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/213/1108/","ar":6,"by":{"0":"28, 30","1":"11, 25","2":"35"}},{"t":"case","label":"Arizona v. United States","cite":"567 U.S. 387","y":2012,"id":"2011/11-182","sc":1,"sum":"The Court found that Arizona's state immigration provisions conflicted in part with federal immigration laws.","sumSrc":"Oyez","by":{"0":"48"}},{"t":"case","label":"AT&T Co. v. Central Office Telephone, Inc.","cite":"524 U.S. 214","y":1998,"id":"1997/97-679","sc":1,"op":1,"sum":"The Court held that Communications Act's filed-tariff requirements pre-empt Central Office Telephone, Inc.'s state-law claims.","sumSrc":"Oyez","by":{"0":"53","2":"64"}},{"t":"case","label":"Boarhead Corp. v. Erickson","cite":"923 F.2d 1011","y":1991,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/923/1011/","by":{"0":"28, 32","2":"35"}},{"t":"case","label":"Broward Gardens Tenants Association v. EPA","cite":"311 F.3d 1066","y":2002,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/311/1066/","by":{"0":"28","1":"19","2":"35"}},{"t":"case","label":"Burlington Northern & Santa Fe Railway Co. v. United States","cite":"556 U.S. 599","y":2009,"id":"2008/07-1601","sc":1,"op":1,"sum":"The Court found that the defendants were not liable as the \"arranger\" for the contamination at issue, and therefore the liability calculations of the district court were appropriate.","sumSrc":"Oyez","by":{"0":"28, 32, 33, 48","1":"2, 19, 33","2":"3, 4, 5, 37","3":"7"}},{"t":"case","label":"Carson Harbor Village, Ltd. v. Unocal Corp.","cite":"270 F.3d 863","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/270/863/","by":{"0":"37"}},{"t":"case","label":"Chicago & North Western Transportation Co. v. Kalo Brick & Tile Co.","cite":"450 U.S. 311","y":1981,"id":"1980/79-1336","sc":1,"sum":"The Interstate Commerce Act precludes a shipper from pressing a state-court action for damages against a regulated rail carrier when, as here, the ICC, in approving the carrier's application for abandonment, reaches the merits of the matters the shipper seeks to raise in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"53"}},{"t":"case","label":"Christian v. Atlantic Richfield Co.","cite":"358 P.3d 131","y":2015,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/358/131/","op":2,"by":{"0":"19, 29, 55","2":"11","3":"15, 16"}},{"t":"case","label":"Cipollone v. Liggett Group, Inc.","cite":"505 U.S. 504","y":1992,"id":"1991/90-1038","sc":1,"sum":"In a complicated 7-to-2 decision, the Court held that federally mandated warnings do not bar smokers from suing manufacturers under state personal-injury laws. The justices ruled that such suits cannot be based on claims that cigarette advertising failed to warn smokers of smoking dangers.","sumSrc":"Oyez","by":{"0":"43","2":"64"}},{"t":"case","label":"Clinton County Commissioners v. EPA","cite":"116 F.3d 1018","y":1997,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/116/1018/","by":{"0":"26"}},{"t":"case","label":"Cooper Industries, Inc. v. Aviall Services, Inc.","cite":"543 U.S. 157","y":2004,"id":"2004/02-1192","sc":1,"op":2,"sum":"The Court held that a private party, who, like Aviall, had not been sued under CERCLA could not obtain cleanup contributions from other liable parties. The Court reasoned that CERCLA's language made clear that parties could seek cleanup contribution only during or following a civil action.","sumSrc":"Oyez","by":{"0":"33","1":"27, 33","2":"5, 37, 38, 39","3":"7"}},{"t":"case","label":"Crosby v. National Foreign Trade Council","cite":"530 U.S. 363","y":2000,"id":"1999/99-474","sc":1,"sum":"The Court held that \"the state Act is preempted, and its application unconstitutional, under the Supremacy Clause.\" Justice Souter wrote for the Court that Massachusetts' law created an obstacle to the President's discretion to control economic sanctions against Burma, interfered with Congress's intention to limit economic pressure against the Burmese Government, and was at odds with the President's authority to speak for the United States among the world's nations to develop a comprehensive, multilateral Burma strategy.","sumSrc":"Oyez","by":{"0":"47, 48"}},{"t":"case","label":"El Paso Natural Gas Co. v. United States","cite":"750 F.3d 863","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/750/863/","by":{"0":"28","2":"35"}},{"t":"case","label":"English v. General Electric Co.","cite":"496 U.S. 72","y":1990,"id":"1989/89-152","sc":1,"sum":"English's state-law claim for intentional infliction of emotional distress is not pre-empted by federal law.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47","2":"59"}},{"t":"case","label":"Fort Ord Toxics Project, Inc. v. California EPA","cite":"189 F.3d 828","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/189/828/","by":{"0":"27, 30","1":"25, 26, 27","2":"23, 26"}},{"t":"case","label":"Geier v. American Honda Motor Co.","cite":"529 U.S. 861","y":2000,"id":"1999/98-1811","sc":1,"ar":1,"sum":"The Court held that \"[Geier's] 'no airbag' lawsuit conflicts with the objectives of FMVSS 208 and is therefore pre-empted by the Act.\" Justice Breyer wrote for the Court that a rule of state tort law imposing a duty to install airbags in cars such as Honda's would have presented an obstacle to the variety and mix of devices that the federal regulation sought and to the phase-in that the federal regulation deliberately imposed.","sumSrc":"Oyez","by":{"0":"47, 52, 53","1":"31","2":"57, 64","3":"24"}},{"t":"case","label":"Hines v. Davidowitz","cite":"312 U.S. 52","y":1941,"id":"scdb/1940-064","sc":1,"sum":"1. Applicable legislation enacted while the case was pending on appeal will be enforced by the appellate court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"case","label":"Maryland v. Louisiana","cite":"451 U.S. 725","y":1981,"id":"1980/83_orig","sc":1,"op":2,"sum":"In this original action, several States, joined by the United States, the Federal Energy Regulatory Commission (FERC), and a number of pipeline companies, challenge the constitutionality of Louisiana's tax on the \"first use\" of any natural gas brought into Louisiana which was not previously subjected to taxation by another State or the United States. The primary effect of the tax, which is imposed on pipeline …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"McClellan Ecological Seepage Situation v. Perry","cite":"47 F.3d 325","y":1995,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/47/325/","by":{"0":"31","1":"20, 26","2":"35"}},{"t":"case","label":"Merck Sharp & Dohme Corp. v. Albrecht","cite":"139 S. Ct. 1668","y":2019,"id":"2018/17-290","sc":1,"sum":"“Clear evidence” that the FDA would not have approved a change to a drug’s label—thus pre-empting a state-law failure-to-warn claim—is evidence showing that the drug manufacturer fully informed the FDA of the justifications for the warning required by state law and that the FDA, in turn, informed the drug manufacturer that the FDA would not approve a change to the drug’s label to include that warning; the question of agency disapproval is primarily one of law for a judge to decide.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"43","1":"31","2":"53, 54, 55"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"0":"53","2":"64"}},{"t":"case","label":"Mutual Pharmaceutical Co. v. Bartlett","cite":"570 U.S. 472","y":2013,"id":"2012/12-142","sc":1,"sum":"The Court found that federal law preempts state law design-defect claims.","sumSrc":"Oyez","by":{"0":"41, 42, 43, 46","1":"31","2":"51, 53","3":"17"}},{"t":"case","label":"New Mexico v. General Electric Co.","cite":"467 F.3d 1223","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/467/1223/","op":2,"by":{"0":"28","1":"19, 32","2":"35, 60"}},{"t":"case","label":"PLIVA, Inc. v. Mensing","cite":"564 U.S. 604","y":2011,"id":"2010/09-993","sc":1,"sum":"The Court held that generic drug makers cannot be sued for not warning about potentially dangerous side effects on their drug labels, even when they follow federal rules that only require their labels to match those of their brand-name equivalents.","sumSrc":"Oyez","by":{"0":"42, 45, 46, 47","2":"53, 54, 55","3":"19, 20"}},{"t":"case","label":"Schalk v. Reilly","cite":"900 F.2d 1091","y":1990,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/900/1091/","by":{"0":"28","2":"35"}},{"t":"case","label":"Sunburst School District No. 2 v. Texaco, Inc.","cite":"165 P.3d 1079","y":2007,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/165/1079/","op":4,"ar":2,"by":{"0":"17, 43, 44","1":"8, 9, 20","2":"10, 11, 34, 49, 51, 52","3":"18"}},{"t":"case","label":"Texas & Pacific Railway Co. v. Abilene Cotton Oil Co.","cite":"204 U.S. 426","y":1907,"id":"scdb/1906-159","sc":1,"op":1,"sum":"Where defendant in the state court contends that, consistently, with the Interstate Commerce Act, the state court hks no power to grant the relief, and such contention is essentially involved and expressly, and, in order to support the judgment, necessarily, decided adversely to the defendant, a Federal question exists and this court' can review the judgment on writ of error under § 709,'.Rev. Stat.'","sumSrc":"Headnote (U.S. Reports)","by":{"0":"53","3":"24"}},{"t":"case","label":"United States v. Atlantic Research Corp.","cite":"551 U.S. 128","y":2007,"id":"2006/06-562","sc":1,"op":2,"sum":"The Court ruled unanimously that Section 107(a) of CERCLA allows potentially responsible parties (PRPs) to sue other PRPs for cost recovery. The opinion by Justice Clarence Thomas affirmed the Eighth Circuit and ruled for Atlantic Research.","sumSrc":"Oyez","by":{"0":"32, 36","1":"23, 27, 33, 34","2":"37, 38, 39","3":"7, 9"}},{"t":"case","label":"United States v. Bestfoods","cite":"524 U.S. 51","y":1998,"id":"1997/97-454","sc":1,"sum":"But a corporate parent that actively participated in, and exercised control over, the operations of the facility itself may be held directly liable in its own right as an operator of the facility.","sumSrc":"Oyez","by":{"0":"28, 36","3":"7"}},{"t":"case","label":"United States v. Gonzales","cite":"520 U.S. 1","y":1997,"id":"1996/95-1605","sc":1,"sum":"In a 7-to-2 decision delivered by Justice Sandra Day O'Connor, the Court announced \"[t]he plain language of (the law) forbids a district court to direct that a term of imprisonment under the statute run concurrently with any other term of imprisonment, whether state or federal.\".","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"United States v. Locke","cite":"529 U.S. 89","y":2000,"id":"1999/98-1701","sc":1,"sum":"The Court held that Washington's regulations regarding general navigation watch procedures, crew English-language skills and training, and maritime casualty reporting are pre-empted by the comprehensive federal regulatory scheme governing oil tankers. \"The State of Washington has enacted legislation in an area where the federal interest has been manifest since the beginning of our Republic and is now well established,\" wrote Justice Kennedy for the Court.","sumSrc":"Oyez","by":{"0":"52"}},{"t":"case","label":"Virginia Uranium, Inc. v. Warren","cite":"139 S. Ct. 1894","y":2019,"id":"2018/16-1275","sc":1,"op":3,"sum":"The Fourth Circuit’s judgment that the Atomic Energy Act does not preempt Virginia’s prohibition on uranium mining in the Commonwealth is affirmed.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"48","2":"64, 65, 66"}},{"t":"case","label":"Wyeth v. Levine","cite":"555 U.S. 555","y":2009,"id":"2008/06-1249","sc":1,"sum":"The Court held that federal law did not preempt state law in a personal injury action against a drug manufacturer for failing to include an appropriate warning label, even where the drug in question met the Food and Drug Administration's (FDA) labeling requirements.","sumSrc":"Oyez","by":{"0":"41, 42","2":"50, 53, 54, 56, 60, 64","3":"19"}},{"t":"const","label":"Article VI","clauses":[["supremacy","Supremacy Clause"],["religious-test","No Religious Test Clause"]],"text":"All Debts contracted and Engagements entered into, before the Adoption of this Constitution, shall be as valid against the United States under this Constitution, as under the Confederation. This Constitution, and the Laws of the United States which shall be made in Pursuance thereof; and all Treaties made, or which shall be made, under the Authority of the United States, shall be the supreme Law of the Land; and the Judges in every State shall be bound thereby, any Thing in the Constitution or Laws of any State to the Contrary notwithstanding. The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"0":"3"}},{"t":"usc","label":"15 U.S.C. § 1397","url":"https://www.law.cornell.edu/uscode/text/15/1397","subs":["(k)(1988)"],"by":{"0":"52"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","subs":["(a)"],"stext":{"head":"§1257. State courts; certiorari","paras":[[0,"(a) Final judgments or decrees rendered by the highest court of a State in which a decision could be had, may be reviewed by the Supreme Court by writ of certiorari where the validity of a treaty or statute of the United States is drawn in question or where the validity of a statute of any State is drawn in question on the ground of its being repugnant to the Constitution, treaties, or laws of the United States, or where any title, right, privilege, or immunity is specially set up or claimed under the Constitution or the treaties or statutes of, or any commission held or authority exercised under, the United States."],[0,"(b) For the purposes of this section, the term \"highest court of a State\" includes the District of Columbia Court of Appeals."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1257?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1257. State courts; certiorari","tname":"Judiciary and Judicial Procedure","by":{"0":"1","1":"14, 15, 16, 17, 23, 24","2":"18, 19, 21"}},{"t":"usc","label":"42 U.S.C. § 9601","url":"https://www.law.cornell.edu/uscode/text/42/9601","subs":["(9)","(9)(B)","(24)","(25)","(35)","(40)"],"stext":{"head":"§9601. Definitions","paras":[[0,"For purpose of this subchapter—"],[1,"(1) The term \"act of God\" means an unanticipated grave natural disaster or other natural phenomenon of an exceptional, inevitable, and irresistible character, the effects of which could not have been prevented or avoided by the exercise of due care or foresight."],[1,"(2) The term \"Administrator\" means the Administrator of the United States Environmental Protection Agency."],[1,"(3) The term \"barrel\" means forty-two United States gallons at sixty degrees Fahrenheit."],[1,"(4) The term \"claim\" means a demand in writing for a sum certain."],[1,"(5) The term \"claimant\" means any person who presents a claim for compensation under this chapter."],[1,"(6) The term \"damages\" means damages for injury or loss of natural resources as set forth in section 9607(a) or 9611(b) of this title."],[1,"(7) The term \"drinking water supply\" means any raw or finished water source that is or may be used by a public water system (as defined in the Safe Drinking Water Act [42 U.S.C. 300f et seq.]) or as drinking water by one or more individuals."],[1,"(8) The term \"environment\" means (A) the navigable waters, the waters of the contiguous zone, and the ocean waters of which the natural resources are under the exclusive management authority of the United States under the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.], and (B) any other surface water, ground water, drinking water supply, land surface or subsurface strata, or ambient air within the United States or under the jurisdiction of the United States."],[1,"(9) The term \"facility\" means (A) any building, structure, installation, equipment, pipe or pipeline (including any pipe into a sewer or publicly owned treatment works), well, pit, pond, lagoon, impoundment, ditch, landfill, storage container, motor vehicle, rolling stock, or aircraft, or (B) any site or area where a hazardous substance has been deposited, stored, disposed of, or placed, or otherwise come to be located; but does not include any consumer product in consumer use or any vessel."],[1,"(10) The term \"federally permitted release\" means (A) discharges in compliance with a permit under section 402 of the Federal Water Pollution Control Act [33 U.S.C. 1342], (B) discharges resulting from circumstances identified and reviewed and made part of the public record with respect to a permit issued or modified under section 402 of the Federal Water Pollution Control Act and subject to a condition of such permit, (C) continuous or anticipated intermittent discharges from a point source, identified in a permit or permit application under section 402 of the Federal Water Pollution Control Act, which are caused by events occurring within the scope of relevant operating or treatment systems, (D) discharges in compliance with a legally enforceable permit under section 404 of the Federal Water Pollution Control Act [33 U.S.C. 1344], (E) releases in compliance with a legally enforceable final permit issued pursuant to section 3005(a) through (d) of the Solid Waste Disposal Act [42 U.S.C. 6925(a)–(d)] from a hazardous waste treatment, storage, or disposal facility when such permit specifically identifies the hazardous substances and makes such substances subject to a standard of practice, control procedure or bioassay limitation or condition, or other control on the hazardous substances in such releases, (F) any release in compliance with a legally enforceable permit issued under section 1412 of title 33 of 1 section 1413 of title 33, (G) any injection of fluids authorized under Federal underground injection control programs or State programs submitted for Federal approval (and not disapproved by the Administrator of the Environmental Protection Agency) pursuant to part C of the Safe Drinking Water Act [42 U.S.C. 300h et seq.], (H) any emission into the air subject to a permit or control regulation under section 111 [42 U.S.C. 7411], section 112 [42 U.S.C. 7412], title I part C [42 U.S.C. 7470 et seq.], title I part D [42 U.S.C. 7501 et seq.], or State implementation plans submitted in accordance with section 110 of the Clean Air Act [42 U.S.C. 7410] (and not disapproved by the Administrator of the Environmental Protection Agency), including any schedule or waiver granted, promulgated, or approved under these sections, (I) any injection of fluids or other materials authorized under applicable State law (i) for the purpose of stimulating or treating wells for the production of crude oil, natural gas, or water, (ii) for the purpose of secondary, tertiary, or other enhanced recovery of crude oil or natural gas, or (iii) which are brought to the surface in conjunction with the production of crude oil or natural gas and which are reinjected, (J) the introduction of any pollutant into a publicly owned treatment works when such pollutant is specified in and in compliance with applicable pretreatment standards of section 307(b) or (c) of the Clean Water Act [33 U.S.C. 1317(b), (c)] and enforceable requirements in a pretreatment program submitted by a State or municipality for Federal approval under section 402 of such Act [33 U.S.C. 1342], and (K) any release of source, special nuclear, or byproduct material, as those terms are defined in the Atomic Energy Act of 1954 [42 U.S.C. 2011 et seq.], in compliance with a legally enforceable license, permit, regulation, or order issued pursuant to the Atomic Energy Act of 1954."],[1,"(11) The term \"Fund\" or \"Trust Fund\" means the Hazardous Substance Superfund established by section 9507 of title 26."],[1,"(12) The term \"ground water\" means water in a saturated zone or stratum beneath the surface of land or water."],[1,"(13) The term \"guarantor\" means any person, other than the owner or operator, who provides evidence of financial responsibility for an owner or operator under this chapter."],[1,"(14) The term \"hazardous substance\" means (A) any substance designated pursuant to section 311(b)(2)(A) of the Federal Water Pollution Control Act [33 U.S.C. 1321(b)(2)(A)], (B) any element, compound, mixture, solution, or substance designated pursuant to section 9602 of this title, (C) any hazardous waste having the characteristics identified under or listed pursuant to section 3001 of the Solid Waste Disposal Act [42 U.S.C. 6921] (but not including any waste the regulation of which under the Solid Waste Disposal Act [42 U.S.C. 6901 et seq.] has been suspended by Act of Congress), (D) any toxic pollutant listed under section 307(a) of the Federal Water Pollution Control Act [33 U.S.C. 1317(a)], (E) any hazardous air pollutant listed under section 112 of the Clean Air Act [42 U.S.C. 7412], and (F) any imminently hazardous chemical substance or mixture with respect to which the Administrator has taken action pursuant to section 7 of the Toxic Substances Control Act [15 U.S.C. 2606]. The term does not include petroleum, including crude oil or any fraction thereof which is not otherwise specifically listed or designated as a hazardous substance under subparagraphs (A) through (F) of this paragraph, and the term does not include natural gas, natural gas liquids, liquefied natural gas, or synthetic gas usable for fuel (or mixtures of natural gas and such synthetic gas)."],[1,"(15) The term \"navigable waters\" or \"navigable waters of the United States\" means the waters of the United States, including the territorial seas."],[1,"(16) The term \"natural resources\" means land, fish, wildlife, biota, air, water, ground water, drinking water supplies, and other such resources belonging to, managed by, held in trust by, appertaining to, or otherwise controlled by the United States (including the resources of the fishery conservation zone established by the Magnuson-Stevens Fishery Conservation and Management Act [16 U.S.C. 1801 et seq.]), any State or local government, any foreign government, any Indian tribe, or, if such resources are subject to a trust restriction on alienation, any member of an Indian tribe."],[1,"(17) The term \"offshore facility\" means any facility of any kind located in, on, or under, any of the navigable waters of the United States, and any facility of any kind which is subject to the jurisdiction of the United States and is located in, on, or under any other waters, other than a vessel or a public vessel."],[1,"(18) The term \"onshore facility\" means any facility (including, but not limited to, motor vehicles and rolling stock) of any kind located in, on, or under, any land or nonnavigable waters within the United States."],[1,"(19) The term \"otherwise subject to the jurisdiction of the United States\" means subject to the jurisdiction of the United States by virtue of United States citizenship, United States vessel documentation or numbering, or as provided by international agreement to which the United States is a party."],[1,"(20)(A) The term \"owner or operator\" means (i) in the case of a vessel, any person owning, operating, or chartering by demise, such vessel, (ii) in the case of an onshore facility or an offshore facility, any person owning or operating such facility, and (iii) in the case of any facility, title or control of which was conveyed due to bankruptcy, foreclosure, tax delinquency, abandonment, or similar means to a unit of State or local government, any person who owned, operated, or otherwise controlled activities at such facility immediately beforehand. Such term does not include a person, who, without participating in the management of a vessel or facility, holds indicia of ownership primarily to protect his security interest in the vessel or facility."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9601?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§9601. Definitions","tname":"The Public Health and Welfare","by":{"0":"33","1":"1, 33, 33, 3","2":"48, 49","3":"9"}},{"t":"reg","label":"40 C.F.R. § 300.425","url":"https://www.ecfr.gov/current/title-40/section-300.425","by":{"0":"9"}},{"t":"reg","label":"48 Fed. Reg. 40,658","url":"https://www.govinfo.gov/link/fr/48/40658","by":{"0":"11","1":"5"}},{"t":"case","label":"Bandini Petroleum Co. v. Superior Court","cite":"284 U.S. 8","y":1931,"id":"scdb/1931-019","sc":1,"sum":"that the statute is not invalid on its face for uncertainty, so as to deprive a state court of jurisdiction to consider relevant questions of fact and determine with respect to a particular field whether there has been the unreasonable waste that the statute condemns. P.*16.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17","2":"20","3":"3"}},{"t":"case","label":"Board of Educ. v. Superior Court","cite":"448 U.S. 1343","y":1980,"url":"https://supreme.justia.com/cases/federal/us/448/1343/","sc":1,"sum":"Concluding that the Court “would in all probability have jurisdiction” over a state court’s resolution of a “petition for a writ of mandamus and/or prohibition” because that petition “was a distinct lawsuit which was fully and finally determined by” a state supreme court.","sumSrc":"brief:1","by":{"1":"17"}},{"t":"case","label":"CTS Corp. v. Waldburger","cite":"573 U.S. 1","y":2014,"id":"2013/13-339","sc":1,"op":1,"ar":1,"sum":"The Court found that the Comprehensive Environmental Response, Compensation, and Liability Act pre-empts statutes of limitations, but cannot be used to pre-empt statutes of repose.","sumSrc":"Oyez","by":{"1":"28","2":"4, 46, 50, 62"}},{"t":"case","label":"Fisher v. District Court","cite":"424 U.S. 382","y":1976,"id":"1975/75-5366","sc":1,"op":2,"sum":"Tribal Court of the Northern Cheyenne Tribe held to have exclusive jurisdiction over an adoption proceeding arising on the Northern Cheyenne Indian Reservation in which all parties are members of the Tribe residing on the reservation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16, 17, 18","2":"20","3":"2, 3"}},{"t":"case","label":"Gade v. National Solid Wastes Mgmt. Ass’n","cite":"505 U.S. 88","y":1992,"id":"1991/90-1676","sc":1,"sum":"The judgment is affirmed. 918 F. 2d 671, affirmed. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, III, and IV, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Gunn v. Minton","cite":"568 U.S. 251","y":2013,"id":"2012/11-1118","sc":1,"op":1,"sum":"The Court found that even though federal courts have exclusive jurisdiction over patent law cases, state courts can still hear cases related to patent law as long as that it is not the primary issue.","sumSrc":"Oyez","by":{"1":"23","2":"25"}},{"t":"case","label":"Heckler v. Ringer","cite":"466 U.S. 602","y":1984,"id":"1983/82-1772","sc":1,"sum":"Part A of Title XVIII of the Social Security Act, commonly known as the Medicare Act, provides insurance for the cost of hospital and related posthospital expenses, but precludes reimbursement for services which are not \"reasonable and necessary\" for the diagnosis or treatment of illness or injury. Judicial review of a claim under the Medicare Act is available only after the Secretary of Health and Human Services …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"International Paper Co. v. Ouellette","cite":"479 U.S. 481","y":1987,"id":"1986/85-1233","sc":1,"sum":"The Clean Water Act (Act) prohibits the discharge of effluents into navigable waters unless the point source has obtained a permit from the Environmental Protection Agency (EPA). The Act also allows the State in which the point source is located (the \"source State\") to impose more stringent discharge limitations than the federal ones, and even to administer its own permit program if certain requirements are met. In …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 32"}},{"t":"case","label":"Jefferson v. City of Tarrant","cite":"522 U.S. 75","y":1997,"id":"1997/96-957","sc":1,"op":1,"sum":"In an 8-1 decision the Court found that it lacked jurisdiction. The opinion by Justice Ruth Bader Ginsburg held that the Court could not rule until the Alabama Supreme Court proceedings were completed and a final decision handed down. The case was dismissed.","sumSrc":"Oyez","by":{"1":"16","2":"18"}},{"t":"case","label":"Jones v. R. R. Donnelley & Sons Co.","cite":"541 U.S. 369","y":2004,"id":"2003/02-1205","sc":1,"sum":"It also applies to amendments of previously existing laws. Writing for a unanimous Court, Justice John Paul Stevens stated \"[a]n amendment to an existing statute is no less an 'Act of Congress' than a new, stand-alone statute.\" The four-year statute of limitations therefore applies to any act or amendment to an act passed by Congress after 1990.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Kennerly v. District Court","cite":"400 U.S. 423","y":1971,"id":"1970/5370","sc":1,"sum":"The Tribal Council's unilateral action was insufficient to vest jurisdiction in the Montana courts under either the 1953 Act, which required affirmative state legislative action, or under the 1968 Act, which calls for a majority vote of all enrolled Indians. Certiorari granted; 154 Mont. 488, 466 P. 2d 85, vacated apd remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16","2":"20","3":"2"}},{"t":"case","label":"Key Tronic Corp. v. United States","cite":"511 U.S. 809","y":1994,"id":"1993/93-376","sc":1,"sum":"CERCLA § 107 does not provide for the award of private litigants' attorney's fees associated with bringing a cost recovery action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3","2":"4","3":"7"}},{"t":"case","label":"Lampi v. Speed","cite":"261 P.3d 1000","y":2011,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/261/1000/","op":1,"by":{"1":"9"}},{"t":"case","label":"Merit Mgmt. Grp., LP v. FTI Consulting, Inc.","cite":"138 S. Ct. 883","y":2018,"id":"2017/16-784","sc":1,"sum":"The Court held that the safe harbor provision of 11 U.S.C. § 546(e), which prohibits a trustee from avoiding a transfer made by or to a financial institution, does not include transfers where the benefit and detriment of the transfer impact companies that are not financial institutions.","sumSrc":"Oyez","by":{"1":"25","2":"27"}},{"t":"case","label":"Oneok, Inc. v. Learjet, Inc.","cite":"135 S. Ct. 1591","y":2015,"id":"2014/13-271","sc":1,"sum":"The Court held that the Natural Gas Act does not pre-empt state law claims brought by litigants who purchased gas in retail transactions.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Verlinden B. V. v. Central Bank of Nigeria","cite":"461 U.S. 480","y":1983,"id":"1982/81-920","sc":1,"op":1,"sum":"The Supreme Court held that the FSIA does not violate Article III. The FSIA was a valid exercise of Congress’ power to regulate foreign commerce. On remand, the court of appeals should consider whether Central Bank is entitled to sovereign immunity.","sumSrc":"Oyez","by":{"1":"24, 25"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"23"}},{"t":"usc","label":"42 U.S.C. § 9604","url":"https://www.law.cornell.edu/uscode/text/42/9604","stext":{"head":"§9604. Response authorities","paras":[[0,"(a) Removal and other remedial action by President; applicability of national contingency plan; response by potentially responsible parties; public health threats; limitations on response; exception"],[0,"(1) Whenever (A) any hazardous substance is released or there is a substantial threat of such a release into the environment, or (B) there is a release or substantial threat of release into the environment of any pollutant or contaminant which may present an imminent and substantial danger to the public health or welfare, the President is authorized to act, consistent with the national contingency plan, to remove or arrange for the removal of, and provide for remedial action relating to such hazardous substance, pollutant, or contaminant at any time (including its removal from any contaminated natural resource), or take any other response measure consistent with the national contingency plan which the President deems necessary to protect the public health or welfare or the environment. When the President determines that such action will be done properly and promptly by the owner or operator of the facility or vessel or by any other responsible party, the President may allow such person to carry out the action, conduct the remedial investigation, or conduct the feasibility study in accordance with section 9622 of this title. No remedial investigation or feasibility study (RI/FS) shall be authorized except on a determination by the President that the party is qualified to conduct the RI/FS and only if the President contracts with or arranges for a qualified person to assist the President in overseeing and reviewing the conduct of such RI/FS and if the responsible party agrees to reimburse the Fund for any cost incurred by the President under, or in connection with, the oversight contract or arrangement. In no event shall a potentially responsible party be subject to a lesser standard of liability, receive preferential treatment, or in any other way, whether direct or indirect, benefit from any such arrangements as a response action contractor, or as a person hired or retained by such a response action contractor, with respect to the release or facility in question. The President shall give primary attention to those releases which the President deems may present a public health threat."],[0,"(2) Removal Action.—Any removal action undertaken by the President under this subsection (or by any other person referred to in section 9622 of this title) should, to the extent the President deems practicable, contribute to the efficient performance of any long term remedial action with respect to the release or threatened release concerned."],[0,"(3) Limitations on Response.—The President shall not provide for a removal or remedial action under this section in response to a release or threat of release—"],[1,"(A) of a naturally occurring substance in its unaltered form, or altered solely through naturally occurring processes or phenomena, from a location where it is naturally found;"],[1,"(B) from products which are part of the structure of, and result in exposure within, residential buildings or business or community structures; or"],[1,"(C) into public or private drinking water supplies due to deterioration of the system through ordinary use."],[0,"(4) Exception to Limitations.—Notwithstanding paragraph (3) of this subsection, to the extent authorized by this section, the President may respond to any release or threat of release if in the President's discretion, it constitutes a public health or environmental emergency and no other person with the authority and capability to respond to the emergency will do so in a timely manner."],[0,"(b) Investigations, monitoring, coordination, etc., by President"],[0,"(1) Information; studies and investigations"],[1,"Whenever the President is authorized to act pursuant to subsection (a) of this section, or whenever the President has reason to believe that a release has occurred or is about to occur, or that illness, disease, or complaints thereof may be attributable to exposure to a hazardous substance, pollutant, or contaminant and that a release may have occurred or be occurring, he may undertake such investigations, monitoring, surveys, testing, and other information gathering as he may deem necessary or appropriate to identify the existence and extent of the release or threat thereof, the source and nature of the hazardous substances, pollutants or contaminants involved, and the extent of danger to the public health or welfare or to the environment. In addition, the President may undertake such planning, legal, fiscal, economic, engineering, architectural, and other studies or investigations as he may deem necessary or appropriate to plan and direct response actions, to recover the costs thereof, and to enforce the provisions of this chapter."],[0,"(2) Coordination of investigations"],[1,"The President shall promptly notify the appropriate Federal and State natural resource trustees of potential damages to natural resources resulting from releases under investigation pursuant to this section and shall seek to coordinate the assessments, investigations, and planning under this section with such Federal and State trustees."],[0,"(c) Criteria for continuance of obligations from Fund over specified amount for response actions; consultation by President with affected States; contracts or cooperative agreements by States with President prior to remedial actions; cost-sharing agreements; selection by President of remedial actions; State credits: granting of credit, expenses before listing or agreement, response actions between 1978 and 1980, State expenses after December 11, 1980, in excess of 10 percent of costs, item-by-item approval, use of credits; operation and maintenance; limitation on source of funds for O&M; recontracting; siting"],[0,"(1) Unless (A) the President finds that (i) continued response actions are immediately required to prevent, limit, or mitigate an emergency, (ii) there is an immediate risk to public health or welfare or the environment, and (iii) such assistance will not otherwise be provided on a timely basis, or (B) the President has determined the appropriate remedial actions pursuant to paragraph (2) of this subsection and the State or States in which the source of the release is located have complied with the requirements of paragraph (3) of this subsection, or (C) continued response action is otherwise appropriate and consistent with the remedial action to be taken 1 obligations from the Fund, other than those authorized by subsection (b) of this section, shall not continue after $2,000,000 has been obligated for response actions or 12 months has elapsed from the date of initial response to a release or threatened release of hazardous substances."],[0,"(2) The President shall consult with the affected State or States before determining any appropriate remedial action to be taken pursuant to the authority granted under subsection (a) of this section."],[0,"(3) The President shall not provide any remedial actions pursuant to this section unless the State in which the release occurs first enters into a contract or cooperative agreement with the President providing assurances deemed adequate by the President that (A) the State will assure all future maintenance of the removal and remedial actions provided for the expected life of such actions as determined by the President; (B) the State will assure the availability of a hazardous waste disposal facility acceptable to the President and in compliance with the requirements of subtitle C of the Solid Waste Disposal Act [42 U.S.C. 6921 et seq.] for any necessary offsite storage, destruction, treatment, or secure disposition of the hazardous substances; and (C) the State will pay or assure payment of (i) 10 per centum of the costs of the remedial action, including all future maintenance, or (ii) 50 percent (or such greater amount as the President may determine appropriate, taking into account the degree of responsibility of the State or political subdivision for the release) of any sums expended in response to a release at a facility, that was operated by the State or a political subdivision thereof, either directly or through a contractual relationship or otherwise, at the time of any disposal of hazardous substances therein. For the purpose of clause (ii) of this subparagraph, the term \"facility\" does not include navigable waters or the beds underlying those waters. In the case of remedial action to be taken on land or water held by an Indian tribe, held by the United States in trust for Indians, held by a member of an Indian tribe (if such land or water is subject to a trust restriction on alienation), or otherwise within the borders of an Indian reservation, the requirements of this paragraph for assurances regarding future maintenance and cost-sharing shall not apply, and the President shall provide the assurance required by this paragraph regarding the availability of a hazardous waste disposal facility."],[0,"(4) Selection of Remedial Action.—The President shall select remedial actions to carry out this section in accordance with section 9621 of this title (relating to cleanup standards)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9604?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§9604. Response authorities","tname":"The Public Health and Welfare","by":{"1":"3, 28","2":"22, 32"}},{"t":"usc","label":"42 U.S.C. § 9605","url":"https://www.law.cornell.edu/uscode/text/42/9605","stext":{"head":"§9605. National contingency plan","paras":[[0,"(a) Revision and republication"],[0,"Within one hundred and eighty days after December 11, 1980, the President shall, after notice and opportunity for public comments, revise and republish the national contingency plan for the removal of oil and hazardous substances, originally prepared and published pursuant to section 1321 of title 33, to reflect and effectuate the responsibilities and powers created by this chapter, in addition to those matters specified in section 1321(c)(2) 1 of title 33. Such revision shall include a section of the plan to be known as the national hazardous substance response plan which shall establish procedures and standards for responding to releases of hazardous substances, pollutants, and contaminants, which shall include at a minimum:"],[1,"(1) methods for discovering and investigating facilities at which hazardous substances have been disposed of or otherwise come to be located;"],[1,"(2) methods for evaluating, including analyses of relative cost, and remedying any releases or threats of releases from facilities which pose substantial danger to the public health or the environment;"],[1,"(3) methods and criteria for determining the appropriate extent of removal, remedy, and other measures authorized by this chapter;"],[1,"(4) appropriate roles and responsibilities for the Federal, State, and local governments and for interstate and nongovernmental entities in effectuating the plan;"],[1,"(5) provision for identification, procurement, maintenance, and storage of response equipment and supplies;"],[1,"(6) a method for and assignment of responsibility for reporting the existence of such facilities which may be located on federally owned or controlled properties and any releases of hazardous substances from such facilities;"],[1,"(7) means of assuring that remedial action measures are cost-effective over the period of potential exposure to the hazardous substances or contaminated materials;"],[1,"(8)(A) criteria for determining priorities among releases or threatened releases throughout the United States for the purpose of taking remedial action and, to the extent practicable taking into account the potential urgency of such action, for the purpose of taking removal action. Criteria and priorities under this paragraph shall be based upon relative risk or danger to public health or welfare or the environment, in the judgment of the President, taking into account to the extent possible the population at risk, the hazard potential of the hazardous substances at such facilities, the potential for contamination of drinking water supplies, the potential for direct human contact, the potential for destruction of sensitive ecosystems, the damage to natural resources which may affect the human food chain and which is associated with any release or threatened release, the contamination or potential contamination of the ambient air which is associated with the release or threatened release, State preparedness to assume State costs and responsibilities, and other appropriate factors;"],[1,"(B) based upon the criteria set forth in subparagraph (A) of this paragraph, the President shall list as part of the plan national priorities among the known releases or threatened releases throughout the United States and shall revise the list no less often than annually. Within one year after December 11, 1980, and annually thereafter, each State shall establish and submit for consideration by the President priorities for remedial action among known releases and potential releases in that State based upon the criteria set forth in subparagraph (A) of this paragraph. In assembling or revising the national list, the President shall consider any priorities established by the States. To the extent practicable, the highest priority facilities shall be designated individually and shall be referred to as the \"top priority among known response targets\", and, to the extent practicable, shall include among the one hundred highest priority facilities one such facility from each State which shall be the facility designated by the State as presenting the greatest danger to public health or welfare or the environment among the known facilities in such State. A State shall be allowed to designate its highest priority facility only once. Other priority facilities or incidents may be listed singly or grouped for response priority purposes;"],[1,"(9) specified roles for private organizations and entities in preparation for response and in responding to releases of hazardous substances, including identification of appropriate qualifications and capacity therefor and including consideration of minority firms in accordance with subsection (f); and"],[1,"(10) standards and testing procedures by which alternative or innovative treatment technologies can be determined to be appropriate for utilization in response actions authorized by this chapter."],[0,"The plan shall specify procedures, techniques, materials, equipment, and methods to be employed in identifying, removing, or remedying releases of hazardous substances comparable to those required under section 1321(c)(2)(F) and (G) and (j)(1) of title 33. Following publication of the revised national contingency plan, the response to and actions to minimize damage from hazardous substances releases shall, to the greatest extent possible, be in accordance with the provisions of the plan. The President may, from time to time, revise and republish the national contingency plan."],[0,"(b) Revision of plan"],[0,"Not later than 18 months after the enactment of the Superfund Amendments and Reauthorization Act of 1986 [October 17, 1986], the President shall revise the National Contingency Plan to reflect the requirements of such amendments. The portion of such Plan known as \"the National Hazardous Substance Response Plan\" shall be revised to provide procedures and standards for remedial actions undertaken pursuant to this chapter which are consistent with amendments made by the Superfund Amendments and Reauthorization Act of 1986 relating to the selection of remedial action."],[0,"(c) Hazard ranking system"],[0,"(1) Revision"],[1,"Not later than 18 months after October 17, 1986, and after publication of notice and opportunity for submission of comments in accordance with section 553 of title 5, the President shall by rule promulgate amendments to the hazard ranking system in effect on September 1, 1984. Such amendments shall assure, to the maximum extent feasible, that the hazard ranking system accurately assesses the relative degree of risk to human health and the environment posed by sites and facilities subject to review. The President shall establish an effective date for the amended hazard ranking system which is not later than 24 months after October 17, 1986. Such amended hazard ranking system shall be applied to any site or facility to be newly listed on the National Priorities List after the effective date established by the President. Until such effective date of the regulations, the hazard ranking system in effect on September 1, 1984, shall continue in full force and effect."],[0,"(2) Health assessment of water contamination risks"],[1,"In carrying out this subsection, the President shall ensure that the human health risks associated with the contamination or potential contamination (either directly or as a result of the runoff of any hazardous substance or pollutant or contaminant from sites or facilities) of surface water are appropriately assessed where such surface water is, or can be, used for recreation or potable water consumption. In making the assessment required pursuant to the preceding sentence, the President shall take into account the potential migration of any hazardous substance or pollutant or contaminant through such surface water to downstream sources of drinking water."],[0,"(3) Reevaluation not required"],[1,"The President shall not be required to reevaluate, after October 17, 1986, the hazard ranking of any facility which was evaluated in accordance with the criteria under this section before the effective date of the amendments to the hazard ranking system under this subsection and which was assigned a national priority under the National Contingency Plan."],[0,"(4) New information"],[1,"Nothing in paragraph (3) shall preclude the President from taking new information into account in undertaking response actions under this chapter."],[0,"(d) Petition for assessment of release"],[0,"Any person who is, or may be, affected by a release or threatened release of a hazardous substance or pollutant or contaminant, may petition the President to conduct a preliminary assessment of the hazards to public health and the environment which are associated with such release or threatened release. If the President has not previously conducted a preliminary assessment of such release, the President shall, within 12 months after the receipt of any such petition, complete such assessment or provide an explanation of why the assessment is not appropriate. If the preliminary assessment indicates that the release or threatened release concerned may pose a threat to human health or the environment, the President shall promptly evaluate such release or threatened release in accordance with the hazard ranking system referred to in paragraph (8)(A) of subsection (a) to determine the national priority of such release or threatened release."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9605?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9605. National contingency plan","tname":"The Public Health and Welfare","by":{"1":"3, 4"}},{"t":"usc","label":"42 U.S.C. § 9606","url":"https://www.law.cornell.edu/uscode/text/42/9606","subs":["(a)"],"stext":{"head":"§9606. Abatement actions","paras":[[0,"(a) Maintenance, jurisdiction, etc."],[0,"In addition to any other action taken by a State or local government, when the President determines that there may be an imminent and substantial endangerment to the public health or welfare or the environment because of an actual or threatened release of a hazardous substance from a facility, he may require the Attorney General of the United States to secure such relief as may be necessary to abate such danger or threat, and the district court of the United States in the district in which the threat occurs shall have jurisdiction to grant such relief as the public interest and the equities of the case may require. The President may also, after notice to the affected State, take other action under this section including, but not limited to, issuing such orders as may be necessary to protect public health and welfare and the environment."],[0,"(b) Fines; reimbursement"],[0,"(1) Any person who, without sufficient cause, willfully violates, or fails or refuses to comply with, any order of the President under subsection (a) may, in an action brought in the appropriate United States district court to enforce such order, be fined not more than $25,000 for each day in which such violation occurs or such failure to comply continues."],[0,"(2)(A) Any person who receives and complies with the terms of any order issued under subsection (a) may, within 60 days after completion of the required action, petition the President for reimbursement from the Fund for the reasonable costs of such action, plus interest. Any interest payable under this paragraph shall accrue on the amounts expended from the date of expenditure at the same rate as specified for interest on investments of the Hazardous Substance Superfund established under subchapter A of chapter 98 of title 26."],[0,"(B) If the President refuses to grant all or part of a petition made under this paragraph, the petitioner may within 30 days of receipt of such refusal file an action against the President in the appropriate United States district court seeking reimbursement from the Fund."],[0,"(C) Except as provided in subparagraph (D), to obtain reimbursement, the petitioner shall establish by a preponderance of the evidence that it is not liable for response costs under section 9607(a) of this title and that costs for which it seeks reimbursement are reasonable in light of the action required by the relevant order."],[0,"(D) A petitioner who is liable for response costs under section 9607(a) of this title may also recover its reasonable costs of response to the extent that it can demonstrate, on the administrative record, that the President's decision in selecting the response action ordered was arbitrary and capricious or was otherwise not in accordance with law. Reimbursement awarded under this subparagraph shall include all reasonable response costs incurred by the petitioner pursuant to the portions of the order found to be arbitrary and capricious or otherwise not in accordance with law."],[0,"(E) Reimbursement awarded by a court under subparagraph (C) or (D) may include appropriate costs, fees, and other expenses in accordance with subsections (a) and (d) of section 2412 of title 28."],[0,"(c) Guidelines for using imminent hazard, enforcement, and emergency response authorities; promulgation by Administrator of EPA, scope, etc."],[0,"Within one hundred and eighty days after December 11, 1980, the Administrator of the Environmental Protection Agency shall, after consultation with the Attorney General, establish and publish guidelines for using the imminent hazard, enforcement, and emergency response authorities of this section and other existing statutes administered by the Administrator of the Environmental Protection Agency to effectuate the responsibilities and powers created by this chapter. Such guidelines shall to the extent practicable be consistent with the national hazardous substance response plan, and shall include, at a minimum, the assignment of responsibility for coordinating response actions with the issuance of administrative orders, enforcement of standards and permits, the gathering of information, and other imminent hazard and emergency powers authorized by (1) sections 1321(c)(2),1 1318, 1319, and 1364(a) of title 33, (2) sections 6927, 6928, 6934, and 6973 of this title, (3) sections 300j–4 and 300i of this title, (4) sections 7413, 7414, and 7603 of this title, and (5) section 2606 of title 15."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9606?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9606. Abatement actions","tname":"The Public Health and Welfare","by":{"1":"3, 28, 24","2":"22, 46, 65"}},{"t":"usc","label":"42 U.S.C. § 9607","url":"https://www.law.cornell.edu/uscode/text/42/9607","subs":["(a)","(a)(1)","(q)","(r)"],"stext":{"head":"§9607. Liability","paras":[[0,"(a) Covered persons; scope; recoverable costs and damages; interest rate; \"comparable maturity\" date"],[0,"Notwithstanding any other provision or rule of law, and subject only to the defenses set forth in subsection (b) of this section—"],[1,"(1) the owner and operator of a vessel or a facility,"],[1,"(2) any person who at the time of disposal of any hazardous substance owned or operated any facility at which such hazardous substances were disposed of,"],[1,"(3) any person who by contract, agreement, or otherwise arranged for disposal or treatment, or arranged with a transporter for transport for disposal or treatment, of hazardous substances owned or possessed by such person, by any other party or entity, at any facility or incineration vessel owned or operated by another party or entity and containing such hazardous substances, and"],[1,"(4) any person who accepts or accepted any hazardous substances for transport to disposal or treatment facilities, incineration vessels or sites selected by such person, from which there is a release, or a threatened release which causes the incurrence of response costs, of a hazardous substance, shall be liable for—"],[2,"(A) all costs of removal or remedial action incurred by the United States Government or a State or an Indian tribe not inconsistent with the national contingency plan;"],[2,"(B) any other necessary costs of response incurred by any other person consistent with the national contingency plan;"],[2,"(C) damages for injury to, destruction of, or loss of natural resources, including the reasonable costs of assessing such injury, destruction, or loss resulting from such a release; and"],[2,"(D) the costs of any health assessment or health effects study carried out under section 9604(i) of this title."],[0,"The amounts recoverable in an action under this section shall include interest on the amounts recoverable under subparagraphs (A) through (D). Such interest shall accrue from the later of (i) the date payment of a specified amount is demanded in writing, or (ii) the date of the expenditure concerned. The rate of interest on the outstanding unpaid balance of the amounts recoverable under this section shall be the same rate as is specified for interest on investments of the Hazardous Substance Superfund established under subchapter A of chapter 98 of title 26. For purposes of applying such amendments to interest under this subsection, the term \"comparable maturity\" shall be determined with reference to the date on which interest accruing under this subsection commences."],[0,"(b) Defenses"],[0,"There shall be no liability under subsection (a) of this section for a person otherwise liable who can establish by a preponderance of the evidence that the release or threat of release of a hazardous substance and the damages resulting therefrom were caused solely by—"],[1,"(1) an act of God;"],[1,"(2) an act of war;"],[1,"(3) an act or omission of a third party other than an employee or agent of the defendant, or than one whose act or omission occurs in connection with a contractual relationship, existing directly or indirectly, with the defendant (except where the sole contractual arrangement arises from a published tariff and acceptance for carriage by a common carrier by rail), if the defendant establishes by a preponderance of the evidence that (a) he exercised due care with respect to the hazardous substance concerned, taking into consideration the characteristics of such hazardous substance, in light of all relevant facts and circumstances, and (b) he took precautions against foreseeable acts or omissions of any such third party and the consequences that could foreseeably result from such acts or omissions; or"],[1,"(4) any combination of the foregoing paragraphs."],[0,"(c) Determination of amounts"],[0,"(1) Except as provided in paragraph (2) of this subsection, the liability under this section of an owner or operator or other responsible person for each release of a hazardous substance or incident involving release of a hazardous substance shall not exceed—"],[1,"(A) for any vessel, other than an incineration vessel, which carries any hazardous substance as cargo or residue, $300 per gross ton, or $5,000,000, whichever is greater;"],[1,"(B) for any other vessel, other than an incineration vessel, $300 per gross ton, or $500,000, whichever is greater;"],[1,"(C) for any motor vehicle, aircraft, hazardous liquid pipeline facility (as defined in section 60101(a) of title 49), or rolling stock, $50,000,000 or such lesser amount as the President shall establish by regulation, but in no event less than $5,000,000 (or, for releases of hazardous substances as defined in section 9601(14)(A) of this title into the navigable waters, $8,000,000). Such regulations shall take into account the size, type, location, storage, and handling capacity and other matters relating to the likelihood of release in each such class and to the economic impact of such limits on each such class; or"],[1,"(D) for any incineration vessel or any facility other than those specified in subparagraph (C) of this paragraph, the total of all costs of response plus $50,000,000 for any damages under this subchapter."],[0,"(2) Notwithstanding the limitations in paragraph (1) of this subsection, the liability of an owner or operator or other responsible person under this section shall be the full and total costs of response and damages, if (A)(i) the release or threat of release of a hazardous substance was the result of willful misconduct or willful negligence within the privity or knowledge of such person, or (ii) the primary cause of the release was a violation (within the privity or knowledge of such person) of applicable safety, construction, or operating standards or regulations; or (B) such person fails or refuses to provide all reasonable cooperation and assistance requested by a responsible public official in connection with response activities under the national contingency plan with respect to regulated carriers subject to the provisions of title 49 or vessels subject to the provisions of title 33 or 46, subparagraph (A)(ii) of this paragraph shall be deemed to refer to Federal standards or regulations."],[0,"(3) If any person who is liable for a release or threat of release of a hazardous substance fails without sufficient cause to properly provide removal or remedial action upon order of the President pursuant to section 9604 or 9606 of this title, such person may be liable to the United States for punitive damages in an amount at least equal to, and not more than three times, the amount of any costs incurred by the Fund as a result of such failure to take proper action. The President is authorized to commence a civil action against any such person to recover the punitive damages, which shall be in addition to any costs recovered from such person pursuant to section 9612(c) of this title. Any moneys received by the United States pursuant to this subsection shall be deposited in the Fund."],[0,"(d) Rendering care or advice"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), no person shall be liable under this subchapter for costs or damages as a result of actions taken or omitted in the course of rendering care, assistance, or advice in accordance with the National Contingency Plan (\"NCP\") or at the direction of an onscene coordinator appointed under such plan, with respect to an incident creating a danger to public health or welfare or the environment as a result of any releases of a hazardous substance or the threat thereof. This paragraph shall not preclude liability for costs or damages as the result of negligence on the part of such person."],[0,"(2) State and local governments"],[1,"No State or local government shall be liable under this subchapter for costs or damages as a result of actions taken in response to an emergency created by the release or threatened release of a hazardous substance generated by or from a facility owned by another person. This paragraph shall not preclude liability for costs or damages as a result of gross negligence or intentional misconduct by the State or local government. For the purpose of the preceding sentence, reckless, willful, or wanton misconduct shall constitute gross negligence."],[0,"(3) Savings provision"],[1,"This subsection shall not alter the liability of any person covered by the provisions of paragraph (1), (2), (3), or (4) of subsection (a) of this section with respect to the release or threatened release concerned."],[0,"(e) Indemnification, hold harmless, etc., agreements or conveyances; subrogation rights"],[0,"(1) No indemnification, hold harmless, or similar agreement or conveyance shall be effective to transfer from the owner or operator of any vessel or facility or from any person who may be liable for a release or threat of release under this section, to any other person the liability imposed under this section. Nothing in this subsection shall bar any agreement to insure, hold harmless, or indemnify a party to such agreement for any liability under this section."],[0,"(2) Nothing in this subchapter, including the provisions of paragraph (1) of this subsection, shall bar a cause of action that an owner or operator or any other person subject to liability under this section, or a guarantor, has or would have, by reason of subrogation or otherwise against any person."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9607?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§9607. Liability","tname":"The Public Health and Welfare","by":{"1":"24, 24","2":"5, 13, 16, 37, 38, 39, 41, 44, 47, 48, 49, 5, 16, 47, 48, 49"}},{"t":"usc","label":"42 U.S.C. § 9613","url":"https://www.law.cornell.edu/uscode/text/42/9613","subs":["(a)","(b)","(h)","(h)(1)","(h)(4)","(k)","(k)(2)","(g)","(j)"],"stext":{"head":"§9613. Civil proceedings","paras":[[0,"(a) Review of regulations in Circuit Court of Appeals of the United States for the District of Columbia"],[0,"Review of any regulation promulgated under this chapter may be had upon application by any interested person only in the Circuit Court of Appeals of the United States for the District of Columbia. Any such application shall be made within ninety days from the date of promulgation of such regulations. Any matter with respect to which review could have been obtained under this subsection shall not be subject to judicial review in any civil or criminal proceeding for enforcement or to obtain damages or recovery of response costs."],[0,"(b) Jurisdiction; venue"],[0,"Except as provided in subsections (a) and (h) of this section, the United States district courts shall have exclusive original jurisdiction over all controversies arising under this chapter, without regard to the citizenship of the parties or the amount in controversy. Venue shall lie in any district in which the release or damages occurred, or in which the defendant resides, may be found, or has his principal office. For the purposes of this section, the Fund shall reside in the District of Columbia."],[0,"(c) Controversies or other matters resulting from tax collection or tax regulation review"],[0,"The provisions of subsections (a) and (b) of this section shall not apply to any controversy or other matter resulting from the assessment of collection of any tax, as provided by subchapter II 1 of this chapter, or to the review of any regulation promulgated under title 26."],[0,"(d) Litigation commenced prior to December 11, 1980"],[0,"No provision of this chapter shall be deemed or held to moot any litigation concerning any release of any hazardous substance, or any damages associated therewith, commenced prior to December 11, 1980."],[0,"(e) Nationwide service of process"],[0,"In any action by the United States under this chapter, process may be served in any district where the defendant is found, resides, transacts business, or has appointed an agent for the service of process."],[0,"(f) Contribution"],[0,"(1) Contribution"],[1,"Any person may seek contribution from any other person who is liable or potentially liable under section 9607(a) of this title, during or following any civil action under section 9606 of this title or under section 9607(a) of this title. Such claims shall be brought in accordance with this section and the Federal Rules of Civil Procedure, and shall be governed by Federal law. In resolving contribution claims, the court may allocate response costs among liable parties using such equitable factors as the court determines are appropriate. Nothing in this subsection shall diminish the right of any person to bring an action for contribution in the absence of a civil action under section 9606 of this title or section 9607 of this title."],[0,"(2) Settlement"],[1,"A person who has resolved its liability to the United States or a State in an administrative or judicially approved settlement shall not be liable for claims for contribution regarding matters addressed in the settlement. Such settlement does not discharge any of the other potentially liable persons unless its terms so provide, but it reduces the potential liability of the others by the amount of the settlement."],[0,"(3) Persons not party to settlement"],[1,"(A) If the United States or a State has obtained less than complete relief from a person who has resolved its liability to the United States or the State in an administrative or judicially approved settlement, the United States or the State may bring an action against any person who has not so resolved its liability."],[1,"(B) A person who has resolved its liability to the United States or a State for some or all of a response action or for some or all of the costs of such action in an administrative or judicially approved settlement may seek contribution from any person who is not party to a settlement referred to in paragraph (2)."],[1,"(C) In any action under this paragraph, the rights of any person who has resolved its liability to the United States or a State shall be subordinate to the rights of the United States or the State. Any contribution action brought under this paragraph shall be governed by Federal law."],[0,"(g) Period in which action may be brought"],[0,"(1) Actions for natural resource damages"],[1,"Except as provided in paragraphs (3) and (4), no action may be commenced for damages (as defined in section 9601(6) of this title) under this chapter, unless that action is commenced within 3 years after the later of the following:"],[2,"(A) The date of the discovery of the loss and its connection with the release in question."],[2,"(B) The date on which regulations are promulgated under section 9651(c) of this title."],[1,"With respect to any facility listed on the National Priorities List (NPL), any Federal facility identified under section 9620 of this title (relating to Federal facilities), or any vessel or facility at which a remedial action under this chapter is otherwise scheduled, an action for damages under this chapter must be commenced within 3 years after the completion of the remedial action (excluding operation and maintenance activities) in lieu of the dates referred to in subparagraph (A) or (B). In no event may an action for damages under this chapter with respect to such a vessel or facility be commenced (i) prior to 60 days after the Federal or State natural resource trustee provides to the President and the potentially responsible party a notice of intent to file suit, or (ii) before selection of the remedial action if the President is diligently proceeding with a remedial investigation and feasibility study under section 9604(b) of this title or section 9620 of this title (relating to Federal facilities). The limitation in the preceding sentence on commencing an action before giving notice or before selection of the remedial action does not apply to actions filed on or before October 17, 1986."],[0,"(2) Actions for recovery of costs"],[1,"An initial action for recovery of the costs referred to in section 9607 of this title must be commenced—"],[2,"(A) for a removal action, within 3 years after completion of the removal action, except that such cost recovery action must be brought within 6 years after a determination to grant a waiver under section 9604(c)(1)(C) of this title for continued response action; and"],[2,"(B) for a remedial action, within 6 years after initiation of physical on-site construction of the remedial action, except that, if the remedial action is initiated within 3 years after the completion of the removal action, costs incurred in the removal action may be recovered in the cost recovery action brought under this subparagraph."],[1,"In any such action described in this subsection, the court shall enter a declaratory judgment on liability for response costs or damages that will be binding on any subsequent action or actions to recover further response costs or damages. A subsequent action or actions under section 9607 of this title for further response costs at the vessel or facility may be maintained at any time during the response action, but must be commenced no later than 3 years after the date of completion of all response action. Except as otherwise provided in this paragraph, an action may be commenced under section 9607 of this title for recovery of costs at any time after such costs have been incurred."],[0,"(3) Contribution"],[1,"No action for contribution for any response costs or damages may be commenced more than 3 years after—"],[2,"(A) the date of judgment in any action under this chapter for recovery of such costs or damages, or"],[2,"(B) the date of an administrative order under section 9622(g) of this title (relating to de minimis settlements) or 9622(h) of this title (relating to cost recovery settlements) or entry of a judicially approved settlement with respect to such costs or damages."],[0,"(4) Subrogation"],[1,"No action based on rights subrogated pursuant to this section by reason of payment of a claim may be commenced under this subchapter more than 3 years after the date of payment of such claim."],[0,"(5) Actions to recover indemnification payments"],[1,"Notwithstanding any other provision of this subsection, where a payment pursuant to an indemnification agreement with a response action contractor is made under section 9619 of this title, an action under section 9607 of this title for recovery of such indemnification payment from a potentially responsible party may be brought at any time before the expiration of 3 years from the date on which such payment is made."],[0,"(6) Minors and incompetents"],[1,"The time limitations contained herein shall not begin to run—"],[2,"(A) against a minor until the earlier of the date when such minor reaches 18 years of age or the date on which a legal representative is duly appointed for such minor, or"],[2,"(B) against an incompetent person until the earlier of the date on which such incompetent's incompetency ends or the date on which a legal representative is duly appointed for such incompetent."],[0,"(h) Timing of review"],[0,"No Federal court shall have jurisdiction under Federal law other than under section 1332 of title 28 (relating to diversity of citizenship jurisdiction) or under State law which is applicable or relevant and appropriate under section 9621 of this title (relating to cleanup standards) to review any challenges to removal or remedial action selected under section 9604 of this title, or to review any order issued under section 9606(a) of this title, in any action except one of the following:"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9613?type=usc&year=mostrecent&link-type=html"},"op":9,"head":"§9613. Civil proceedings","tname":"The Public Health and Welfare","by":{"1":"24, 24, 24, 24, 24, 4, 4, 4, 4, 3, 6, 28, 3, 6, 28, 3, 6, 28, 3, 6, 28","2":"6, 6, 15, 23, 24, 25, 26, 27, 28, 31, 5, 36, 2, 4, 6, 7, 12, 13, 14, 15, 16, 21, 22, 23, 27, 28, 29, 30, 31, 32, 33, 34, 35, 60, 61, 63, 33, 45, 46"}},{"t":"usc","label":"42 U.S.C. § 9614","url":"https://www.law.cornell.edu/uscode/text/42/9614","subs":["(a)","(b)"],"stext":{"head":"§9614. Relationship to other law","paras":[[0,"(a) Additional State liability or requirements with respect to release of substances within State"],[0,"Nothing in this chapter shall be construed or interpreted as preempting any State from imposing any additional liability or requirements with respect to the release of hazardous substances within such State."],[0,"(b) Recovery under other State or Federal law of compensation for removal costs or damages, or payment of claims"],[0,"Any person who receives compensation for removal costs or damages or claims pursuant to this chapter shall be precluded from recovering compensation for the same removal costs or damages or claims pursuant to any other State or Federal law. Any person who receives compensation for removal costs or damages or claims pursuant to any other Federal or State law shall be precluded from receiving compensation for the same removal costs or damages or claims as provided in this chapter."],[0,"(c) Recycled oil"],[0,"(1) Service station dealers, etc."],[1,"No person (including the United States or any State) may recover, under the authority of subsection (a)(3) or (a)(4) of section 9607 of this title, from a service station dealer for any response costs or damages resulting from a release or threatened release of recycled oil, or use the authority of section 9606 of this title against a service station dealer other than a person described in subsection (a)(1) or (a)(2) of section 9607 of this title, if such recycled oil—"],[2,"(A) is not mixed with any other hazardous substance, and"],[2,"(B) is stored, treated, transported, or otherwise managed in compliance with regulations or standards promulgated pursuant to section 3014 of the Solid Waste Disposal Act [42 U.S.C. 6935] and other applicable authorities."],[1,"Nothing in this paragraph shall affect or modify in any way the obligations or liability of any person under any other provision of State or Federal law, including common law, for damages, injury, or loss resulting from a release or threatened release of any hazardous substance or for removal or remedial action or the costs of removal or remedial action."],[0,"(2) Presumption"],[1,"Solely for the purposes of this subsection, a service station dealer may presume that a small quantity of used oil is not mixed with other hazardous substances if it—"],[2,"(A) has been removed from the engine of a light duty motor vehicle or household appliances by the owner of such vehicle or appliances, and"],[2,"(B) is presented, by such owner, to the dealer for collection, accumulation, and delivery to an oil recycling facility."],[0,"(3) Definition"],[1,"For purposes of this subsection, the terms \"used oil\" and \"recycled oil\" have the same meanings as set forth in sections 1004(36) and 1004(37) of the Solid Waste Disposal Act [42 U.S.C. 6903(36), (37)] and regulations promulgated pursuant to that Act [42 U.S.C. 6901 et seq.]."],[0,"(4) Effective date"],[1,"The effective date of paragraphs (1) and (2) of this subsection shall be the effective date of regulations or standards promulgated under section 3014 of the Solid Waste Disposal Act [42 U.S.C. 6935] that include, among other provisions, a requirement to conduct corrective action to respond to any releases of recycled oil under subtitle C or subtitle I of such Act [42 U.S.C. 6921 et seq., 6991 et seq.]."],[0,"(d) Financial responsibility of owner or operator of vessel or facility under State or local law, rule, or regulation"],[0,"Except as provided in this subchapter, no owner or operator of a vessel or facility who establishes and maintains evidence of financial responsibility in accordance with this subchapter shall be required under any State or local law, rule, or regulation to establish or maintain any other evidence of financial responsibility in connection with liability for the release of a hazardous substance from such vessel or facility. Evidence of compliance with the financial responsibility requirements of this subchapter shall be accepted by a State in lieu of any other requirement of financial responsibility imposed by such State in connection with liability for the release of a hazardous substance from such vessel or facility."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9614?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9614. Relationship to other law","tname":"The Public Health and Welfare","by":{"1":"3, 6, 28","2":"4, 62, 63, 65, 61, 62"}},{"t":"usc","label":"42 U.S.C. § 9617","url":"https://www.law.cornell.edu/uscode/text/42/9617","by":{"1":"3, 6, 28"}},{"t":"usc","label":"42 U.S.C. § 9621","url":"https://www.law.cornell.edu/uscode/text/42/9621","subs":["(c)","(d)","(d)(4)","(a)","(b)"],"stext":{"head":"§9621. Cleanup standards","paras":[[0,"(a) Selection of remedial action"],[0,"The President shall select appropriate remedial actions determined to be necessary to be carried out under section 9604 of this title or secured under section 9606 of this title which are in accordance with this section and, to the extent practicable, the national contingency plan, and which provide for cost-effective response. In evaluating the cost effectiveness of proposed alternative remedial actions, the President shall take into account the total short- and long-term costs of such actions, including the costs of operation and maintenance for the entire period during which such activities will be required."],[0,"(b) General rules"],[0,"(1) Remedial actions in which treatment which permanently and significantly reduces the volume, toxicity or mobility of the hazardous substances, pollutants, and contaminants is a principal element, are to be preferred over remedial actions not involving such treatment. The offsite transport and disposal of hazardous substances or contaminated materials without such treatment should be the least favored alternative remedial action where practicable treatment technologies are available. The President shall conduct an assessment of permanent solutions and alternative treatment technologies or resource recovery technologies that, in whole or in part, will result in a permanent and significant decrease in the toxicity, mobility, or volume of the hazardous substance, pollutant, or contaminant. In making such assessment, the President shall specifically address the long-term effectiveness of various alternatives. In assessing alternative remedial actions, the President shall, at a minimum, take into account:"],[1,"(A) the long-term uncertainties associated with land disposal;"],[1,"(B) the goals, objectives, and requirements of the Solid Waste Disposal Act [42 U.S.C. 6901 et seq.];"],[1,"(C) the persistence, toxicity, mobility, and propensity to bioaccumulate of such hazardous substances and their constituents;"],[1,"(D) short- and long-term potential for adverse health effects from human exposure;"],[1,"(E) long-term maintenance costs;"],[1,"(F) the potential for future remedial action costs if the alternative remedial action in question were to fail; and"],[1,"(G) the potential threat to human health and the environment associated with excavation, transportation, and redisposal, or containment."],[0,"The President shall select a remedial action that is protective of human health and the environment, that is cost effective, and that utilizes permanent solutions and alternative treatment technologies or resource recovery technologies to the maximum extent practicable. If the President selects a remedial action not appropriate for a preference under this subsection, the President shall publish an explanation as to why a remedial action involving such reductions was not selected."],[0,"(2) The President may select an alternative remedial action meeting the objectives of this subsection whether or not such action has been achieved in practice at any other facility or site that has similar characteristics. In making such a selection, the President may take into account the degree of support for such remedial action by parties interested in such site."],[0,"(c) Review"],[0,"If the President selects a remedial action that results in any hazardous substances, pollutants, or contaminants remaining at the site, the President shall review such remedial action no less often than each 5 years after the initiation of such remedial action to assure that human health and the environment are being protected by the remedial action being implemented. In addition, if upon such review it is the judgment of the President that action is appropriate at such site in accordance with section 9604 or 9606 of this title, the President shall take or require such action. The President shall report to the Congress a list of facilities for which such review is required, the results of all such reviews, and any actions taken as a result of such reviews."],[0,"(d) Degree of cleanup"],[0,"(1) Remedial actions selected under this section or otherwise required or agreed to by the President under this chapter shall attain a degree of cleanup of hazardous substances, pollutants, and contaminants released into the environment and of control of further release at a minimum which assures protection of human health and the environment. Such remedial actions shall be relevant and appropriate under the circumstances presented by the release or threatened release of such substance, pollutant, or contaminant."],[0,"(2)(A) With respect to any hazardous substance, pollutant or contaminant that will remain onsite, if—"],[1,"(i) any standard, requirement, criteria, or limitation under any Federal environmental law, including, but not limited to, the Toxic Substances Control Act [15 U.S.C. 2601 et seq.], the Safe Drinking Water Act [42 U.S.C. 300f et seq.], the Clean Air Act [42 U.S.C. 7401 et seq.], the Clean Water Act [33 U.S.C. 1251 et seq.], the Marine Protection, Research and Sanctuaries Act [16 U.S.C. 1431 et seq., 1447 et seq., 33 U.S.C. 1401 et seq., 2801 et seq.], or the Solid Waste Disposal Act [42 U.S.C. 6901 et seq.]; or"],[1,"(ii) any promulgated standard, requirement, criteria, or limitation under a State environmental or facility siting law that is more stringent than any Federal standard, requirement, criteria, or limitation, including each such State standard, requirement, criteria, or limitation contained in a program approved, authorized or delegated by the Administrator under a statute cited in subparagraph (A), and that has been identified to the President by the State in a timely manner,"],[0,"is legally applicable to the hazardous substance or pollutant or contaminant concerned or is relevant and appropriate under the circumstances of the release or threatened release of such hazardous substance or pollutant or contaminant, the remedial action selected under section 9604 of this title or secured under section 9606 of this title shall require, at the completion of the remedial action, a level or standard of control for such hazardous substance or pollutant or contaminant which at least attains such legally applicable or relevant and appropriate standard, requirement, criteria, or limitation. Such remedial action shall require a level or standard of control which at least attains Maximum Contaminant Level Goals established under the Safe Drinking Water Act [42 U.S.C. 300f et seq.] and water quality criteria established under section 304 or 303 of the Clean Water Act [33 U.S.C. 1314, 1313], where such goals or criteria are relevant and appropriate under the circumstances of the release or threatened release."],[0,"(B)(i) In determining whether or not any water quality criteria under the Clean Water Act [33 U.S.C. 1251 et seq.] is relevant and appropriate under the circumstances of the release or threatened release, the President shall consider the designated or potential use of the surface or groundwater, the environmental media affected, the purposes for which such criteria were developed, and the latest information available."],[0,"(ii) For the purposes of this section, a process for establishing alternate concentration limits to those otherwise applicable for hazardous constituents in groundwater under subparagraph (A) may not be used to establish applicable standards under this paragraph if the process assumes a point of human exposure beyond the boundary of the facility, as defined at the conclusion of the remedial investigation and feasibility study, except where—"],[1,"(I) there are known and projected points of entry of such groundwater into surface water; and"],[1,"(II) on the basis of measurements or projections, there is or will be no statistically significant increase of such constituents from such groundwater in such surface water at the point of entry or at any point where there is reason to believe accumulation of constituents may occur downstream; and"],[1,"(III) the remedial action includes enforceable measures that will preclude human exposure to the contaminated groundwater at any point between the facility boundary and all known and projected points of entry of such groundwater into surface water"],[0,"then the assumed point of human exposure may be at such known and projected points of entry."],[0,"(C)(i) Clause (ii) of this subparagraph shall be applicable only in cases where, due to the President's selection, in compliance with subsection (b)(1), of a proposed remedial action which does not permanently and significantly reduce the volume, toxicity, or mobility of hazardous substances, pollutants, or contaminants, the proposed disposition of waste generated by or associated with the remedial action selected by the President is land disposal in a State referred to in clause (ii)."],[0,"(ii) Except as provided in clauses (iii) and (iv), a State standard, requirement, criteria, or limitation (including any State siting standard or requirement) which could effectively result in the statewide prohibition of land disposal of hazardous substances, pollutants, or contaminants shall not apply."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9621?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§9621. Cleanup standards","tname":"The Public Health and Welfare","by":{"1":"28, 28, 3, 28, 3, 28, 3, 28, 1, 1","2":"60, 33, 8, 23, 33, 56, 61, 40"}},{"t":"usc","label":"42 U.S.C. § 9622","url":"https://www.law.cornell.edu/uscode/text/42/9622","subs":["(e)(6)","(a)","(c)","(e)"],"stext":{"head":"§9622. Settlements","paras":[[0,"(a) Authority to enter into agreements"],[0,"The President, in his discretion, may enter into an agreement with any person (including the owner or operator of the facility from which a release or substantial threat of release emanates, or any other potentially responsible person), to perform any response action (including any action described in section 9604(b) of this title) if the President determines that such action will be done properly by such person. Whenever practicable and in the public interest, as determined by the President, the President shall act to facilitate agreements under this section that are in the public interest and consistent with the National Contingency Plan in order to expedite effective remedial actions and minimize litigation. If the President decides not to use the procedures in this section, the President shall notify in writing potentially responsible parties at the facility of such decision and the reasons why use of the procedures is inappropriate. A decision of the President to use or not to use the procedures in this section is not subject to judicial review."],[0,"(b) Agreements with potentially responsible parties"],[0,"(1) Mixed funding"],[1,"An agreement under this section may provide that the President will reimburse the parties to the agreement from the Fund, with interest, for certain costs of actions under the agreement that the parties have agreed to perform but which the President has agreed to finance. In any case in which the President provides such reimbursement, the President shall make all reasonable efforts to recover the amount of such reimbursement under section 9607 of this title or under other relevant authorities."],[0,"(2) Reviewability"],[1,"The President's decisions regarding the availability of fund financing under this subsection shall not be subject to judicial review under subsection (d)."],[0,"(3) Retention of funds"],[1,"If, as part of any agreement, the President will be carrying out any action and the parties will be paying amounts to the President, the President may, notwithstanding any other provision of law, retain and use such amounts for purposes of carrying out the agreement."],[0,"(4) Future obligation of Fund"],[1,"In the case of a completed remedial action pursuant to an agreement described in paragraph (1), the Fund shall be subject to an obligation for subsequent remedial actions at the same facility but only to the extent that such subsequent actions are necessary by reason of the failure of the original remedial action. Such obligation shall be in a proportion equal to, but not exceeding, the proportion contributed by the Fund for the original remedial action. The Fund's obligation for such future remedial action may be met through Fund expenditures or through payment, following settlement or enforcement action, by parties who were not signatories to the original agreement."],[0,"(c) Effect of agreement"],[0,"(1) Liability"],[1,"Whenever the President has entered into an agreement under this section, the liability to the United States under this chapter of each party to the agreement, including any future liability to the United States, arising from the release or threatened release that is the subject of the agreement shall be limited as provided in the agreement pursuant to a covenant not to sue in accordance with subsection (f). A covenant not to sue may provide that future liability to the United States of a settling potentially responsible party under the agreement may be limited to the same proportion as that established in the original settlement agreement. Nothing in this section shall limit or otherwise affect the authority of any court to review in the consent decree process under subsection (d) any covenant not to sue contained in an agreement under this section. In determining the extent to which the liability of parties to an agreement shall be limited pursuant to a covenant not to sue, the President shall be guided by the principle that a more complete covenant not to sue shall be provided for a more permanent remedy undertaken by such parties."],[0,"(2) Actions against other persons"],[1,"If an agreement has been entered into under this section, the President may take any action under section 9606 of this title against any person who is not a party to the agreement, once the period for submitting a proposal under subsection (e)(2)(B) has expired. Nothing in this section shall be construed to affect either of the following:"],[2,"(A) The liability of any person under section 9606 or 9607 of this title with respect to any costs or damages which are not included in the agreement."],[2,"(B) The authority of the President to maintain an action under this chapter against any person who is not a party to the agreement."],[0,"(d) Enforcement"],[0,"(1) Cleanup agreements"],[0,"(A) Consent decree"],[2,"Whenever the President enters into an agreement under this section with any potentially responsible party with respect to remedial action under section 9606 of this title, following approval of the agreement by the Attorney General, except as otherwise provided in the case of certain administrative settlements referred to in subsection (g), the agreement shall be entered in the appropriate United States district court as a consent decree. The President need not make any finding regarding an imminent and substantial endangerment to the public health or the environment in connection with any such agreement or consent decree."],[0,"(B) Effect"],[2,"The entry of any consent decree under this subsection shall not be construed to be an acknowledgment by the parties that the release or threatened release concerned constitutes an imminent and substantial endangerment to the public health or welfare or the environment. Except as otherwise provided in the Federal Rules of Evidence, the participation by any party in the process under this section shall not be considered an admission of liability for any purpose, and the fact of such participation shall not be admissible in any judicial or administrative proceeding, including a subsequent proceeding under this section."],[0,"(C) Structure"],[2,"The President may fashion a consent decree so that the entering of such decree and compliance with such decree or with any determination or agreement made pursuant to this section shall not be considered an admission of liability for any purpose."],[0,"(2) Public participation"],[0,"(A) Filing of proposed judgment"],[2,"At least 30 days before a final judgment is entered under paragraph (1), the proposed judgment shall be filed with the court."],[0,"(B) Opportunity for comment"],[2,"The Attorney General shall provide an opportunity to persons who are not named as parties to the action to comment on the proposed judgment before its entry by the court as a final judgment. The Attorney General shall consider, and file with the court, any written comments, views, or allegations relating to the proposed judgment. The Attorney General may withdraw or withhold its consent to the proposed judgment if the comments, views, and allegations concerning the judgment disclose facts or considerations which indicate that the proposed judgment is inappropriate, improper, or inadequate."],[0,"(3) 9604(b) agreements"],[1,"Whenever the President enters into an agreement under this section with any potentially responsible party with respect to action under section 9604(b) of this title, the President shall issue an order or enter into a decree setting forth the obligations of such party. The United States district court for the district in which the release or threatened release occurs may enforce such order or decree."],[0,"(e) Special notice procedures"],[0,"(1) Notice"],[1,"Whenever the President determines that a period of negotiation under this subsection would facilitate an agreement with potentially responsible parties for taking response action (including any action described in section 9604(b) of this title) and would expedite remedial action, the President shall so notify all such parties and shall provide them with information concerning each of the following:"],[2,"(A) The names and addresses of potentially responsible parties (including owners and operators and other persons referred to in section 9607(a) of this title), to the extent such information is available."],[2,"(B) To the extent such information is available, the volume and nature of substances contributed by each potentially responsible party identified at the facility."],[2,"(C) A ranking by volume of the substances at the facility, to the extent such information is available."],[1,"The President shall make the information referred to in this paragraph available in advance of notice under this paragraph upon the request of a potentially responsible party in accordance with procedures provided by the President. The provisions of subsection (e) of section 9604 of this title regarding protection of confidential information apply to information provided under this paragraph. Disclosure of information generated by the President under this section to persons other than the Congress, or any duly authorized Committee thereof, is subject to other privileges or protections provided by law, including (but not limited to) those applicable to attorney work product. Nothing contained in this paragraph or in other provisions of this chapter shall be construed, interpreted, or applied to diminish the required disclosure of information under other provisions of this or other Federal or State laws."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9622?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§9622. Settlements","tname":"The Public Health and Welfare","by":{"1":"1","2":"43, 44, 5, 40, 5, 40, 44, 2, 6, 12, 14, 16, 35, 40, 41, 47, 48, 49, 60, 61"}},{"t":"usc","label":"42 U.S.C. § 9652","url":"https://www.law.cornell.edu/uscode/text/42/9652","subs":["(d)"],"stext":{"head":"§9652. Effective dates; savings provisions","paras":[[0,"(a) Unless otherwise provided, all provisions of this chapter shall be effective on December 11, 1980."],[0,"(b) Any regulation issued pursuant to any provisions of section 1321 of title 33 which is repealed or superseded by this chapter and which is in effect on the date immediately preceding the effective date of this chapter shall be deemed to be a regulation issued pursuant to the authority of this chapter and shall remain in full force and effect unless or until superseded by new regulations issued thereunder."],[0,"(c) Any regulation—"],[1,"(1) respecting financial responsibility,"],[1,"(2) issued pursuant to any provision of law repealed or superseded by this chapter, and"],[1,"(3) in effect on the date immediately preceding the effective date of this chapter shall be deemed to be a regulation issued pursuant to the authority of this chapter and shall remain in full force and effect unless or until superseded by new regulations issued thereunder."],[0,"(d) Nothing in this chapter shall affect or modify in any way the obligations or liabilities of any person under other Federal or State law, including common law, with respect to releases of hazardous substances or other pollutants or contaminants. The provisions of this chapter shall not be considered, interpreted, or construed in any way as reflecting a determination, in part or whole, of policy regarding the inapplicability of strict liability, or strict liability doctrines, to activities relating to hazardous substances, pollutants, or contaminants or other such activities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9652?type=usc&year=mostrecent&link-type=html"},"head":"§9652. Effective dates; savings provisions","tname":"The Public Health and Welfare","by":{"1":"1","2":"4, 21, 63"}},{"t":"usc","label":"42 U.S.C. § 9659","url":"https://www.law.cornell.edu/uscode/text/42/9659","subs":["(b)(1)","(b)(2)","(h)","(a)"],"stext":{"head":"§9659. Citizens suits","paras":[[0,"(a) Authority to bring civil actions"],[0,"Except as provided in subsections (d) and (e) of this section and in section 9613(h) of this title (relating to timing of judicial review), any person may commence a civil action on his own behalf—"],[1,"(1) against any person (including the United States and any other governmental instrumentality or agency, to the extent permitted by the eleventh amendment to the Constitution) who is alleged to be in violation of any standard, regulation, condition, requirement, or order which has become effective pursuant to this chapter (including any provision of an agreement under section 9620 of this title, relating to Federal facilities); or"],[1,"(2) against the President or any other officer of the United States (including the Administrator of the Environmental Protection Agency and the Administrator of the ATSDR) where there is alleged a failure of the President or of such other officer to perform any act or duty under this chapter, including an act or duty under section 9620 of this title (relating to Federal facilities), which is not discretionary with the President or such other officer."],[0,"Paragraph (2) shall not apply to any act or duty under the provisions of section 9660 of this title (relating to research, development, and demonstration)."],[0,"(b) Venue"],[0,"(1) Actions under subsection (a)(1)"],[1,"Any action under subsection (a)(1) shall be brought in the district court for the district in which the alleged violation occurred."],[0,"(2) Actions under subsection (a)(2)"],[1,"Any action brought under subsection (a)(2) may be brought in the United States District Court for the District of Columbia."],[0,"(c) Relief"],[0,"The district court shall have jurisdiction in actions brought under subsection (a)(1) to enforce the standard, regulation, condition, requirement, or order concerned (including any provision of an agreement under section 9620 of this title), to order such action as may be necessary to correct the violation, and to impose any civil penalty provided for the violation. The district court shall have jurisdiction in actions brought under subsection (a)(2) to order the President or other officer to perform the act or duty concerned."],[0,"(d) Rules applicable to subsection (a)(1) actions"],[0,"(1) Notice"],[1,"No action may be commenced under subsection (a)(1) before 60 days after the plaintiff has given notice of the violation to each of the following:"],[2,"(A) The President."],[2,"(B) The State in which the alleged violation occurs."],[2,"(C) Any alleged violator of the standard, regulation, condition, requirement, or order concerned (including any provision of an agreement under section 9620 of this title)."],[1,"Notice under this paragraph shall be given in such manner as the President shall prescribe by regulation."],[0,"(2) Diligent prosecution"],[1,"No action may be commenced under paragraph (1) of subsection (a) if the President has commenced and is diligently prosecuting an action under this chapter, or under the Solid Waste Disposal Act [42 U.S.C. 6901 et seq.] to require compliance with the standard, regulation, condition, requirement, or order concerned (including any provision of an agreement under section 9620 of this title)."],[0,"(e) Rules applicable to subsection (a)(2) actions"],[0,"No action may be commenced under paragraph (2) of subsection (a) before the 60th day following the date on which the plaintiff gives notice to the Administrator or other department, agency, or instrumentality that the plaintiff will commence such action. Notice under this subsection shall be given in such manner as the President shall prescribe by regulation."],[0,"(f) Costs"],[0,"The court, in issuing any final order in any action brought pursuant to this section, may award costs of litigation (including reasonable attorney and expert witness fees) to the prevailing or the substantially prevailing party whenever the court determines such an award is appropriate. The court may, if a temporary restraining order or preliminary injunction is sought, require the filing of a bond or equivalent security in accordance with the Federal Rules of Civil Procedure."],[0,"(g) Intervention"],[0,"In any action under this section, the United States or the State, or both, if not a party may intervene as a matter of right. For other provisions regarding intervention, see section 9613 of this title."],[0,"(h) Other rights"],[0,"This chapter does not affect or otherwise impair the rights of any person under Federal, State, or common law, except with respect to the timing of review as provided in section 9613(h) of this title or as otherwise provided in section 9658 of this title (relating to actions under State law)."],[0,"(i) Definitions"],[0,"The terms used in this section shall have the same meanings as when used in subchapter I."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9659?type=usc&year=mostrecent&link-type=html"},"head":"§9659. Citizens suits","tname":"The Public Health and Welfare","by":{"1":"1, 1, 1, 1","2":"27, 4, 63"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1331. Federal question","tname":"Judiciary and Judicial Procedure","by":{"1":"23, 24","2":"24, 26"}},{"t":"usc","label":"28 U.S.C. § 1442","url":"https://www.law.cornell.edu/uscode/text/28/1442","by":{"1":"10"}},{"t":"case","label":"Anderson v. Stokes","cite":"163 P.3d 1273","y":2007,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/163/1273/","by":{"2":"49"}},{"t":"case","label":"Arceneaux v. Louisiana","cite":"376 U.S. 336","y":1964,"id":"1963/76","sc":1,"sum":"Writ of certiorari dismissed for lack of jurisdiction since denial of preliminary hearing in this case is not a \"final\" judgment under 28 U. S. C. § 1257.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20","3":"2"}},{"t":"case","label":"Bates v. Dow Agrosciences LLC","cite":"544 U.S. 431","y":2005,"id":"2004/03-388","sc":1,"sum":"The Court held that the peanut farmers could sue Dow in state court.","sumSrc":"Oyez","by":{"2":"52, 59"}},{"t":"case","label":"Bowen v. Georgetown Univ. Hospital","cite":"488 U.S. 204","y":1988,"id":"1988/87-1097","sc":1,"sum":"Under the Medicare program, the Government reimburses health care providers for expenses incurred in providing medical services to Medicare beneficiaries. The Medicare Act in 42 U. S. C. § 1395x(v)(1)(A) authorizes the Secretary of Health and Human Services (Secretary) to promulgate cost-reimbursement regulations and also provides that \"[s]uch regulations shall... (ii) provide for the making of suitable retroactive …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"47"}},{"t":"case","label":"California v. ARC America Corp.","cite":"490 U.S. 93","y":1989,"id":"1988/87-1862","sc":1,"sum":"The rule limiting federal antitrust recoveries to direct purchasers does not prevent indirect purchasers from recovering damages flowing from state antitrust law violations.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"60"}},{"t":"case","label":"City of Rialto v. West Coast Loading Corp.","cite":"581 F.3d 865","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/581/865/","by":{"2":"32"}},{"t":"case","label":"Cox Broadcasting Corp. v. Cohn","cite":"420 U.S. 469","y":1975,"id":"1974/73-938","sc":1,"sum":"The Court held that the Georgia statute violated the Constitution. Justice White recognized the primacy of issues of privacy and press freedom, but he also identified compelling reasons why the press should not be restricted in this case. First, the news media is an important resource for citizens which allows them to scrutinize government proceedings.","sumSrc":"Oyez","by":{"2":"18, 20, 21","3":"3"}},{"t":"case","label":"CSX Transp. v. Easterwood","cite":"507 U.S. 658","y":1993,"id":"1992/91-790","sc":1,"sum":"Under the FRSA, federal regulations adopted by the Secretary of Transportation pre-empt Easterwood's negligence action only insofar as it asserts that CSX's train was traveling at an excessive speed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"59","3":"21"}},{"t":"case","label":"Cyan, Inc. v. Beaver County Employees Retirement Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"op":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"2":"28, 42"}},{"t":"case","label":"Dep’t of Energy v. Ohio","cite":"503 U.S. 607","y":1992,"id":"1991/90-1341","sc":1,"sum":"Congress has not waived the National Government's sovereign immunity from liability for civil fines imposed by a State for past violations of the CWA or RCRA.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25, 26"}},{"t":"case","label":"Edward J. DeBartolo Corp. v. Florida Gulf Coast Bldg. & Constr. Trades Council","cite":"485 U.S. 568","y":1988,"id":"1987/86-1461","sc":1,"sum":"The Court of Appeals did not err in construing § 8(b)(4) as not reaching respondent's handbilling. That construction makes it unnecessary to pass upon the serious First Amendment questions that would be raised by the Board's interpretation.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Empire Healthchoice Assur., Inc. v. McVeigh","cite":"547 U.S. 677","y":2006,"id":"2005/05-200","sc":1,"sum":"In a 5-to-4 decision authored by Justice Ruth Bader Ginsburg, the Court held that jurisdiction for this case lay in state court. Justice Ginsburg pointed out that while FEHBA stated that any claims against the United States would be heard in federal district court, it made no provisions for suits brought by insurers seeking to recoup medical expenses from private beneficiaries.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Exxon Corp. v. Hunt","cite":"475 U.S. 355","y":1986,"id":"1985/84-978","sc":1,"sum":"The New Jersey Spill Compensation and Control Act (Spill Act), enacted in 1977 to respond to the problem of hazardous substance release, imposes an excise tax upon major petroleum and chemical facilities within the State to finance the prevention and cleanup of oil spills and leaks of hazardous chemicals from disposal sites. The tax revenue goes into a permanent fund (Spill Fund), which may spend money not only to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"Florida Lime & Avocado Growers, Inc. v. Paul","cite":"373 U.S. 132","y":1963,"id":"1962/45","sc":1,"sum":"The Court held that federal law will preempt a state law if it is physically impossible to comply with both laws.","sumSrc":"Oyez","by":{"2":"50"}},{"t":"case","label":"Franchise Tax Bd. of Cal. v. Constr. Laborers Vacation Tr. for S. Cal.","cite":"463 U.S. 1","y":1983,"id":"1982/82-695","sc":1,"sum":"The case is not within the removal jurisdiction conferred by 28 U. S. C. § 1441.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25, 26"}},{"t":"case","label":"Garcia v. United States","cite":"469 U.S. 70","y":1984,"id":"1984/83-6061","sc":1,"sum":"The language \"any money or other property of the United States\" in § 2114 includes the $1,800 belonging to the United States and entrusted to the Secret Service agent as \"flash money,\" and thus by using a pistol in an effort to rob the agent petitioners fell squarely within the prohibitions of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"Garza v. Forquest Ventures, Inc.","cite":"358 P.3d 189","y":2015,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/358/189/","op":1,"by":{"2":"57"}},{"t":"case","label":"Gonzalez v. Raich","cite":"545 U.S. 1","y":2005,"id":"2004/03-1454","sc":1,"sum":"The Court ruled that the commerce clause of the Controlled Substances Act gives Congress authority to prohibit the local cultivation and use of marijuana, despite state law to the contrary.","sumSrc":"Oyez","by":{"2":"42"}},{"t":"case","label":"Grable & Sons Metal Prods., Inc. v. Darue Eng’g & Mfg.","cite":"545 U.S. 308","y":2005,"id":"2004/04-603","sc":1,"sum":"The Court held that the case involved a federal question and could thus be removed to federal court. Federal-questions jurisdiction, the Court reasoned, lay over some state-law claims that implicated significant federal issues. In this case, the national interest in providing a federal forum for federal tax litigation warranted moving the case to federal court.","sumSrc":"Oyez","by":{"2":"25"}},{"t":"case","label":"Loretto v. Teleprompter Manhattan CATV Corp.","cite":"458 U.S. 419","y":1982,"id":"1981/81-244","sc":1,"op":1,"sum":"The New York statute works a taking of a portion of appellant's property for which she is entitled to just compensation under the Fifth Amendment, as made applicable to the States by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"42"}},{"t":"case","label":"Louisiana Public Service Comm’n v. FCC","cite":"476 U.S. 355","y":1986,"id":"1985/84-871","sc":1,"sum":"Section 152(b) bars federal pre-emption of state regulation over depreciation of dual jurisdiction property for intrastate ratemaking purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"59"}},{"t":"case","label":"Madruga v. Superior Court of California","cite":"346 U.S. 556","y":1954,"id":"scdb/1953-024","sc":1,"sum":"Eight individuals who owned undivided interests aggregating 85% in a ship which was certificated under the maritime laws of the United States, instituted a proceeding in a California state court at San Diego, the home port of the vessel, for sale of the vessel and partition of the proceeds pursuant to a California statute. The defendant was an individual who owned a 15% interest in the vessel, and personal service …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Manor Care, Inc. v. Yaskin","cite":"950 F.2d 122","y":1991,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/950/122/","by":{"2":"60, 62"}},{"t":"case","label":"Martin v. Artis","cite":"290 P.3d 687","y":2012,"court":"Mont.","url":"https://www.courtlistener.com/c/P.3d/290/687/","by":{"2":"51"}},{"t":"case","label":"Metro. Life Ins. Co. v. Taylor","cite":"481 U.S. 58","y":1987,"id":"1986/85-686","sc":1,"sum":"Section 502(a)(1)(B) of the Employee Retirement Income Security Act of 1974 (ERISA) provides that a participant or beneficiary may bring a civil action to, inter alia, recover benefits due him under the terms of an employee benefit plan. Under 28 U. S. C. § 1441(a), any civil action brought in state court of which the federal district courts have original jurisdiction may be removed by the defendant to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"24"}},{"t":"case","label":"Missouri ex rel. St. Louis B. & M. Ry. Co. v. Taylor","cite":"266 U.S. 200","y":1924,"id":"scdb/1924-046","sc":1,"sum":"1. A judgment of a state Supreme Court denying an application for a writ of prohibition to prevent a lower court from entertaining jurisdiction by garnishment over an action against a foreign railroad corporation for damage to an interstate shipment, held a final judgment, and reviewable in this Court by certiorari, but not by writ oferror.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Mt. Vernon-Woodberry Cotton Duck Co. v. Ala. Interstate Power Co.","cite":"240 U.S. 30","y":1916,"id":"scdb/1915-069","sc":1,"sum":"Prohibition is a distinct suit and the judgment finally disposing of it is a final judgment by common law as well as'.under the statutes of Alabama within the meaning of Judicial Code, § 237.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Niagara Mohawk Power Corp. v. Chevron U.S.A., Inc.","cite":"596 F.3d 112","y":2010,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/596/112/","by":{"2":"3"}},{"t":"case","label":"North Dakota State Bd. of Pharmacy v. Snyder’s Drug Stores, Inc.","cite":"414 U.S. 156","y":1973,"id":"1973/72-1176","sc":1,"sum":"The N rth Dakota Supreme Court, relying on Liggett Co. v. Baldridge, 278 U. S. 105, held unconstitutional a state statute, under which respondent had been denied a pharmacy operating permit, requiring that an applicant for such a permit be \"a registered pharmacist in good standing\" or \"a corporation or association, the majority stock in which is owned by registered pharmacists in good standing, actively and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"18, 19"}},{"t":"case","label":"North Shore Gas Co. v. EPA","cite":"930 F.2d 1239","y":1991,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/930/1239/","by":{"2":"32"}},{"t":"case","label":"O’Dell v. Espinoza","cite":"456 U.S. 430","y":1982,"id":"1981/81-534","sc":1,"by":{"2":"18"}},{"t":"case","label":"Radio Station WOW, Inc. v. Johnson","cite":"326 U.S. 120","y":1945,"id":"scdb/1944-027","sc":1,"sum":"1. A state court decree otherwise \"final\" for purposes of review by this Court is none the less so because it orders also an accounting of profits, where such accounting can not give rise to a federal question. Judicial Code, § 237.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"19"}},{"t":"case","label":"Rescue Army v. Municipal Court of Los Angeles","cite":"331 U.S. 549","y":1947,"id":"scdb/1946-114","sc":1,"sum":"Being charged in a municipal court in California on two counts with violations of three sections of a municipal code governing the solicitation of contributions for charity, which sections incorporated by reference numerous other sections of an intricate and ambiguous chapter, appellants sued for a writ of prohibition to test the jurisdiction of the trial court, claiming that the code unduly abridged the free …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"Riegel v. Medtronic, Inc.","cite":"552 U.S. 312","y":2008,"id":"2007/06-179","sc":1,"sum":"The Court, in an 8-1 decision, affirmed the Second Circuit and granted summary judgment in favor of Medtronic. The Court's opinion, written by Justice Antonin Scalia, noted that the MDA pre-empted state common law claims for defective devices such as this one.","sumSrc":"Oyez","by":{"2":"51"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"39"}},{"t":"case","label":"Sturgeon v. Frost","cite":"139 S. Ct. 1066","y":2019,"id":"2018/17-949","sc":1,"op":1,"sum":"Alaska’s Nation River is not public land; and like all non-public lands and navigable waters within Alaska’s national parks, it is exempt under the Alaska National Interest Lands Conservation Act from the National Park Service’s ordinary regulatory authority.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"30"}},{"t":"case","label":"Tafflin v. Levitt","cite":"493 U.S. 455","y":1990,"id":"1989/88-1650","sc":1,"op":1,"sum":"State courts have concurrent jurisdiction over civil RICO claims. The presumption in favor of such jurisdiction has not been rebutted by any of the factors identified in Gulf Offshore Co. v. Mobil Oil Corp., 453 U. S. 473, 478.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"26"}},{"t":"case","label":"United States v. Colorado","cite":"990 F.2d 1565","y":1993,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/990/1565/","by":{"2":"33, 42"}},{"t":"case","label":"Vaden v. Discover Bank","cite":"556 U.S. 49","y":2009,"id":"2008/07-773","sc":1,"op":1,"sum":"The Court held that a federal court may \"look through\" a Section 4 petition to determine whether the claim establishes federal subject matter jurisdiction.","sumSrc":"Oyez","by":{"2":"24"}},{"t":"case","label":"Village of DePue, Ill. v. Exxon Mobil Corp.","cite":"537 F.3d 775","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/537/775/","op":1,"by":{"2":"22, 23, 28"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"sum":"After her husband of less than six months died, appellee widow filed applications for mother's Social Security insurance benefits for herself and child's insurance benefits for her daughter by a previous marriage, but the Social Security Administration (SSA), both initially and on reconsideration at the regional level, denied the applications on the basis of the duration-of-relationship requirements of the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"25"}},{"t":"case","label":"Williamson v. Mazda Motor of America, Inc.","cite":"562 U.S. 323","y":2011,"id":"2010/08-1314","sc":1,"sum":"The Court held that a wrongful death lawsuit under California law alleging that Mazda should have installed belt and shoulder seatbelts in the backseat of a minivan is not preempted by a federal regulation that gives automakers the option to install either kind of seatbelts.","sumSrc":"Oyez","by":{"2":"57, 62, 64"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1332. Diversity of citizenship; amount in controversy; costs","tname":"Judiciary and Judicial Procedure","by":{"2":"22"}},{"t":"usc","label":"28 U.S.C. § 1337","url":"https://www.law.cornell.edu/uscode/text/28/1337","by":{"2":"25, 26"}},{"t":"usc","label":"28 U.S.C. § 1338","url":"https://www.law.cornell.edu/uscode/text/28/1338","by":{"2":"25"}},{"t":"usc","label":"42 U.S.C. § 9619","url":"https://www.law.cornell.edu/uscode/text/42/9619","subs":["(d)"],"stext":{"head":"§9619. Response action contractors","paras":[[0,"(a) Liability of response action contractors"],[0,"(1) Response action contractors"],[1,"A person who is a response action contractor with respect to any release or threatened release of a hazardous substance or pollutant or contaminant from a vessel or facility shall not be liable under this subchapter or under any other Federal law to any person for injuries, costs, damages, expenses, or other liability (including but not limited to claims for indemnification or contribution and claims by third parties for death, personal injury, illness or loss of or damage to property or economic loss) which results from such release or threatened release."],[0,"(2) Negligence, etc."],[1,"Paragraph (1) shall not apply in the case of a release that is caused by conduct of the response action contractor which is negligent, grossly negligent, or which constitutes intentional misconduct."],[0,"(3) Effect on warranties; employer liability"],[1,"Nothing in this subsection shall affect the liability of any person under any warranty under Federal, State, or common law. Nothing in this subsection shall affect the liability of an employer who is a response action contractor to any employee of such employer under any provision of law, including any provision of any law relating to worker's compensation."],[0,"(4) Governmental employees"],[1,"A state employee or an employee of a political subdivision who provides services relating to response action while acting within the scope of his authority as a governmental employee shall have the same exemption from liability (subject to the other provisions of this section) as is provided to the response action contractor under this section."],[0,"(b) Savings provisions"],[0,"(1) Liability of other persons"],[1,"The defense provided by section 9607(b)(3) of this title shall not be available to any potentially responsible party with respect to any costs or damages caused by any act or omission of a response action contractor. Except as provided in subsection (a)(4) and the preceding sentence, nothing in this section shall affect the liability under this chapter or under any other Federal or State law of any person, other than a response action contractor."],[0,"(2) Burden of plaintiff"],[1,"Nothing in this section shall affect the plaintiff's burden of establishing liability under this subchapter."],[0,"(c) Indemnification"],[0,"(1) In general"],[1,"The President may agree to hold harmless and indemnify any response action contractor meeting the requirements of this subsection against any liability (including the expenses of litigation or settlement) for negligence arising out of the contractor's performance in carrying out response action activities under this subchapter, unless such liability was caused by conduct of the contractor which was grossly negligent or which constituted intentional misconduct."],[0,"(2) Applicability"],[1,"This subsection shall apply only with respect to a response action carried out under written agreement with—"],[2,"(A) the President;"],[2,"(B) any Federal agency;"],[2,"(C) a State or political subdivision which has entered into a contract or cooperative agreement in accordance with section 9604(d)(1) of this title; or"],[2,"(D) any potentially responsible party carrying out any agreement under section 9622 of this title (relating to settlements) or section 9606 of this title (relating to abatement)."],[0,"(3) Source of funding"],[1,"This subsection shall not be subject to section 1301 or 1341 of title 31 or section 6301(a) and (b) of title 41 or to section 9662 of this title. For purposes of section 9611 of this title, amounts expended pursuant to this subsection for indemnification of any response action contractor (except with respect to federally owned or operated facilities) shall be considered governmental response costs incurred pursuant to section 9604 of this title. If sufficient funds are unavailable in the Hazardous Substance Superfund established under subchapter A of chapter 98 of title 26 to make payments pursuant to such indemnification or if the Fund is repealed, there are authorized to be appropriated such amounts as may be necessary to make such payments."],[0,"(4) Requirements"],[1,"An indemnification agreement may be provided under this subsection only if the President determines that each of the following requirements are met:"],[2,"(A) The liability covered by the indemnification agreement exceeds or is not covered by insurance available, at a fair and reasonable price, to the contractor at the time the contractor enters into the contract to provide response action, and adequate insurance to cover such liability is not generally available at the time the response action contract is entered into."],[2,"(B) The response action contractor has made diligent efforts to obtain insurance coverage from non-Federal sources to cover such liability."],[2,"(C) In the case of a response action contract covering more than one facility, the response action contractor agrees to continue to make such diligent efforts each time the contractor begins work under the contract at a new facility."],[0,"(5) Limitations"],[0,"(A) Liability covered"],[2,"Indemnification under this subsection shall apply only to response action contractor liability which results from a release of any hazardous substance or pollutant or contaminant if such release arises out of response action activities."],[0,"(B) Deductibles and limits"],[2,"An indemnification agreement under this subsection shall include deductibles and shall place limits on the amount of indemnification to be made available."],[0,"(C) Contracts with potentially responsible parties"],[0,"(i) Decision to indemnify"],[3,"In deciding whether to enter into an indemnification agreement with a response action contractor carrying out a written contract or agreement with any potentially responsible party, the President shall determine an amount which the potentially responsible party is able to indemnify the contractor. The President may enter into such an indemnification agreement only if the President determines that such amount of indemnification is inadequate to cover any reasonable potential liability of the contractor arising out of the contractor's negligence in performing the contract or agreement with such party. The President shall make the determinations in the preceding sentences (with respect to the amount and the adequacy of the amount) taking into account the total net assets and resources of potentially responsible parties with respect to the facility at the time of such determinations."],[0,"(ii) Conditions"],[3,"The President may pay a claim under an indemnification agreement referred to in clause (i) for the amount determined under clause (i) only if the contractor has exhausted all administrative, judicial, and common law claims for indemnification against all potentially responsible parties participating in the clean-up of the facility with respect to the liability of the contractor arising out of the contractor's negligence in performing the contract or agreement with such party. Such indemnification agreement shall require such contractor to pay any deductible established under subparagraph (B) before the contractor may recover any amount from the potentially responsible party or under the indemnification agreement."],[0,"(D) RCRA facilities"],[2,"No owner or operator of a facility regulated under the Solid Waste Disposal Act [42 U.S.C. 6901 et seq.] may be indemnified under this subsection with respect to such facility."],[0,"(E) Persons retained or hired"],[2,"A person retained or hired by a person described in subsection (e)(2)(B) shall be eligible for indemnification under this subsection only if the President specifically approves of the retaining or hiring of such person."],[0,"(6) Cost recovery"],[1,"For purposes of section 9607 of this title, amounts expended pursuant to this subsection for indemnification of any person who is a response action contractor with respect to any release or threatened release shall be considered a cost of response incurred by the United States Government with respect to such release."],[0,"(7) Regulations"],[1,"The President shall promulgate regulations for carrying out the provisions of this subsection. Before promulgation of the regulations, the President shall develop guidelines to carry out this section. Development of such guidelines shall include reasonable opportunity for public comment."],[0,"(8) Study"],[1,"The Comptroller General shall conduct a study in the fiscal year ending September 30, 1989, on the application of this subsection, including whether indemnification agreements under this subsection are being used, the number of claims that have been filed under such agreements, and the need for this subsection. The Comptroller General shall report the findings of the study to Congress no later than September 30, 1989."],[0,"(d) Exception"],[0,"The exemption provided under subsection (a) and the authority of the President to offer indemnification under subsection (c) shall not apply to any person covered by the provisions of paragraph (1), (2), (3), or (4) of section 9607(a) of this title with respect to the release or threatened release concerned if such person would be covered by such provisions even if such person had not carried out any actions referred to in subsection (e) of this section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/9619?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§9619. Response action contractors","tname":"The Public Health and Welfare","by":{"2":"39"}},{"t":"usc","label":"42 U.S.C. § 9620","url":"https://www.law.cornell.edu/uscode/text/42/9620","subs":["(e)"],"by":{"2":"40"}},{"t":"usc","label":"42 U.S.C. § 9624","url":"https://www.law.cornell.edu/uscode/text/42/9624","subs":["(b)"],"by":{"2":"39"}},{"t":"usc","label":"42 U.S.C. § 9658","url":"https://www.law.cornell.edu/uscode/text/42/9658","subs":["(a)"],"by":{"2":"4, 62, 63"}},{"t":"law","label":"Pub. L. No. 99-499","url":"https://www.govinfo.gov/link/statute/100/1613","by":{"2":"29"}},{"t":"reg","label":"40 C.F.R. § 300.400","url":"https://www.ecfr.gov/current/title-40/section-300.400","subs":["(g)"],"by":{"2":"61"}},{"t":"case","label":"Detroit & Mackinac Railway Co. v. Michigan Railroad Commission","cite":"240 U.S. 564","y":1916,"id":"scdb/1915-132","sc":1,"sum":"A judgment or decree which determines the particular cause is final in the sense of § 237, Jud. Code.","sumSrc":"Headnote (U.S. Reports)","by":{"3":"3"}},{"t":"case","label":"Graham County Soil & Water Conservation District v. United States ex rel. Wilson","cite":"559 U.S. 280","y":2010,"id":"2009/08-304","sc":1,"sum":"The Court held that an audit performed by a state or its political subdivisions constitutes an administrative report within the False Claims Act.","sumSrc":"Oyez","by":{"3":"12"}},{"t":"case","label":"Johnson v. United States","cite":"559 U.S. 133","y":2010,"id":"2009/08-6925","sc":1,"sum":"The Court held that the Eleventh Circuit Court of Appeals was bound by Florida state law in considering a felony battery charge.","sumSrc":"Oyez","by":{"3":"6"}},{"t":"case","label":"Pennsylvania v. Union Gas Co.","cite":"491 U.S. 1","y":1989,"id":"1988/87-1241","sc":1,"sum":"The judgment is affirmed, and the case is remanded. 832 F. 2d 1343, affirmed and remanded. JUSTICE BRENNAN delivered the opinion of the Court with respect to Parts I and II, concluding that CERCLA, as amended by SARA, clearly expresses an intent to hold States liable in damages in federal court.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"8"}},{"t":"case","label":"Seminole Tribe of Florida v. Florida","cite":"517 U.S. 44","y":1996,"id":"1995/94-12","sc":1,"sum":"In a 5-to-4 decision, The Court held that Congress did intend to abrogate states' sovereign immunity under the IGRA but that the Indian Commerce Clause (and by implication the Commerce Clause) did not give Congress that power. Under the Eleventh Amendment, all states are regarded as sovereign entities.","sumSrc":"Oyez","by":{"3":"8, 10"}},{"t":"case","label":"Weston v. City Council of Charleston","cite":"2 Pet. 449","y":1829,"url":"https://www.courtlistener.com/c/Pet./2/449/","by":{"3":"2, 3"}},{"t":"reg","label":"40 C.F.R. § 300.430","url":"https://www.ecfr.gov/current/title-40/section-300.430","subs":["(f)(1)(i)"],"by":{"3":"22"}}]};